const MANIFEST = {
  "type": "Animation.KineticTypography",
  "description": "Boutique kinetic typography with 13 animation presets, 3D transforms, and sophisticated controls",
  "editorElement": {
    "selector": ".kinetic-typography",
    "displayName": "Kinetic Typography",
    "archetype": "container",
    "data": {
      "text": {
        "dataType": "text",
        "displayName": "Headline Text",
        "defaultValue": "DESIGN EXCELLENCE",
