        "options": ["cubic-bezier(0.22, 1, 0.36, 1)", "cubic-bezier(0.34, 1.56, 0.64, 1)", "cubic-bezier(0.16, 1, 0.3, 1)", "ease-out"],
        "group": "Animation"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
