      },
      "letterSpacing": {
        "dataType": "select",
        "displayName": "Letter Spacing",
        "defaultValue": "0.1em",
        "options": ["0em", "0.025em", "0.05em", "0.075em", "0.1em", "0.15em"],
        "group": "Typography"
      },
      "textAlign": {
        "dataType": "select",
        "displayName": "Text Alignment",
        "defaultValue": "center",
        "options": ["left", "center", "right"],
        "group": "Typography"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const text = config?.text || 'DESIGN EXCELLENCE';
  const showReplayButton = config?.showReplayButton !== false;
  const replayButtonText = config?.replayButtonText || 'Replay Animation';
  const triggerMode = config?.triggerMode || 'entrance';
  const scrollThreshold = parseFloat(config?.scrollThreshold || '0.3');
  const animationPreset = config?.animationPreset || 'wonderland';
  const animationDuration = parseInt(config?.animationDuration || '600');
  const staggerAmount = parseFloat(config?.staggerAmount || '0.8');
  const intensity = config?.intensity || 'medium';
  const easing = config?.easing || 'cubic-bezier(0.22, 1, 0.36, 1)';
  const backgroundColor = config?.backgroundColor || '#18181B';
  const textColor = config?.textColor || '#FAFAFA';
  const buttonTextColor = config?.buttonTextColor || '#A1A1AA';
  const buttonBorderColor = config?.buttonBorderColor || '#3F3F46';
  const buttonHoverColor = config?.buttonHoverColor || '#FAFAFA';
  const fontSize = parseInt(config?.fontSize || '72');
  const fontWeight = config?.fontWeight || '300';
  const letterSpacing = config?.letterSpacing || '0.1em';
  const textAlign = config?.textAlign || 'center';

  const containerRef = React.useRef(null);
  const [animatedIndices, setAnimatedIndices] = React.useState(new Set());
  const [hasAnimated, setHasAnimated] = React.useState(false);
  const [isButtonHovered, setIsButtonHovered] = React.useState(false);

  const prefersReducedMotion = React.useMemo(() => {
    return typeof window !== 'undefined'
      ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
      : false;
  }, []);

  const intensityMultiplier = React.useMemo(() => ({
    subtle: 0.5,
    medium: 1.0,
    dramatic: 1.5
  }[intensity]), [intensity]);

  const characters = React.useMemo(() => {
    return text.split('').map((char, index) => ({
      char: char === ' ' ? '\u00A0' : char,
      index
    }));
  }, [text]);

  const getRandom = (index, seed, min, max) => {
    const x = Math.sin(index * seed) * 10000;
    const random = x - Math.floor(x);
    return min + random * (max - min);
  };

  const getPresetConfig = React.useCallback((charIndex, totalChars) => {
    const position = totalChars > 1 ? charIndex / (totalChars - 1) : 0.5;
    const im = intensityMultiplier;

    const presets = {
      explosive: {
        offsetY: getRandom(charIndex, 1.5, -150, 150) * im,
        offsetX: getRandom(charIndex, 2.3, -200, 200) * im,
        rotation: getRandom(charIndex, 3.7, -180, 180) * im,
        scale: 0.3,
        blur: 15 * im,
        staggerType: 'random',
        use3D: false
      },
      typewriter: {
        offsetY: 0,
        offsetX: -20 * im,
        rotation: 0,
        scale: 1,
        blur: 0,
        staggerType: 'sequential',
        use3D: false
      },
      wave: {
        offsetY: Math.sin(position * Math.PI * 2) * 60 * im,
        offsetX: 0,
        rotation: Math.sin(position * Math.PI * 2) * 15 * im,
        scale: 0.8,
        blur: 5 * im,
        staggerType: 'sequential',
        use3D: false
      },
      glitch: {
        offsetY: getRandom(charIndex, 4.1, -30, 30) * im,
        offsetX: getRandom(charIndex, 5.2, -50, 50) * im,
        rotation: 0,
        scale: getRandom(charIndex, 6.3, 0.5, 1.5),
        blur: getRandom(charIndex, 7.4, 0, 10) * im,
        staggerType: 'random',
        use3D: false
      },
      spiral: {
        offsetY: Math.sin(position * Math.PI * 3) * 100 * im,
        offsetX: Math.cos(position * Math.PI * 3) * 100 * im,
        rotation: 720 * im,
        scale: 0.2,
        blur: 10 * im,
        staggerType: 'sequential',
        use3D: false
      },
      pendulum: {
        offsetY: Math.sin(position * Math.PI) * 80 * im,
        offsetX: (position - 0.5) * 100 * im,
        rotation: (position - 0.5) * 45 * im,
        scale: 0.7,
        blur: 8 * im,
        staggerType: 'edges',
        use3D: false
      },
      quantum: {
        offsetY: ((charIndex % 2) * 2 - 1) * 100 * im,
        offsetX: ((charIndex % 3) - 1) * 80 * im,
        rotation: ((charIndex % 2) * 2 - 1) * 90 * im,
        scale: 0.1 + (charIndex % 3) * 0.3,
        blur: (charIndex % 2) * 15 * im,
        staggerType: 'alternating',
        use3D: false
      },
      cascade: {
        offsetY: -150 * im,
        offsetX: getRandom(charIndex, 8.5, -20, 20) * im,
        rotation: getRandom(charIndex, 9.6, -15, 15) * im,
        scale: 0.8,
        blur: 12 * im,
        staggerType: 'sequential',
        use3D: false
      },
      magnetic: {
        offsetY: (position - 0.5) * 200 * im,
        offsetX: (position - 0.5) * 150 * im,
        rotation: 0,
        scale: 0.2,
        blur: 20 * im,
        staggerType: 'center',
        use3D: false
      },
      origami: {
        offsetY: ((charIndex % 2) * 2 - 1) * 80 * im,
        offsetX: 0,
        rotation: 90 * im,
        scale: 0.1,
        blur: 5 * im,
        staggerType: 'alternating',
        use3D: true,
        rotateX: 90 * im
      },
      ripple: {
        offsetY: Math.sin(Math.abs(position - 0.5) * Math.PI * 2) * 50 * im,
        offsetX: Math.cos(Math.abs(position - 0.5) * Math.PI * 2) * 50 * im,
        rotation: 0,
        scale: 0.5,
        blur: Math.abs(position - 0.5) * 20 * im,
        staggerType: 'center',
        use3D: false
      },
      aurora: {
        offsetY: Math.sin(position * Math.PI * 1.5) * 40 * im,
        offsetX: 0,
        rotation: 0,
        scale: 0.9,
        blur: 8 * im,
        hueRotate: position * 360,
        saturation: 50,
        staggerType: 'sequential',
        use3D: false
      },
      wonderland: {
        offsetY: (40 + Math.sin(charIndex * 0.5) * 40) * im,
        offsetX: Math.sin(charIndex * 0.3) * 25 * im,
        rotation: 0,
        rotateX: (35 + Math.sin(charIndex * 0.4) * 35) * im,
        rotateY: (-40 + Math.cos(charIndex * 0.3) * 40) * im,
        rotateZ: (-18 + Math.sin(charIndex * 0.6) * 18) * im,
        scale: 0.7,
        blur: 8 * im,
        staggerType: 'sequential',
        use3D: true
      }
    };

    return presets[animationPreset] || presets.wonderland;
  }, [animationPreset, intensityMultiplier]);

  const getStaggerOrder = React.useCallback((staggerType, totalChars) => {
    const indices = Array.from({ length: totalChars }, (_, i) => i);

    switch (staggerType) {
      case 'sequential':
        return indices;
      case 'reverse':
        return indices.reverse();
      case 'random':
        return indices.sort(() => getRandom(indices.length, 11.1, -1, 1));
      case 'center':
        const middle = Math.floor(totalChars / 2);
        return indices.sort((a, b) => Math.abs(a - middle) - Math.abs(b - middle));
      case 'edges':
        return indices.sort((a, b) => Math.abs(b - totalChars / 2) - Math.abs(a - totalChars / 2));
      case 'alternating':
        const evens = indices.filter(i => i % 2 === 0);
        const odds = indices.filter(i => i % 2 !== 0);
        return [...evens, ...odds];
      default:
        return indices;
    }
  }, []);

  const animate = React.useCallback(() => {
    if (prefersReducedMotion) {
      setAnimatedIndices(new Set(characters.map((_, i) => i)));
      setHasAnimated(true);
      return;
    }

    setAnimatedIndices(new Set());

    const presetConfig = getPresetConfig(0, characters.length);
    const staggerOrder = getStaggerOrder(presetConfig.staggerType, characters.length);
    const delayPerChar = (staggerAmount * 1000) / characters.length;

    staggerOrder.forEach((charIndex, orderIndex) => {
      setTimeout(() => {
        setAnimatedIndices(prev => {
          const newSet = new Set(prev);
          newSet.add(charIndex);
          return newSet;
        });
      }, orderIndex * delayPerChar);
    });

    setHasAnimated(true);
  }, [characters, staggerAmount, getPresetConfig, getStaggerOrder, prefersReducedMotion]);

  const handleReplay = React.useCallback(() => {
    setHasAnimated(false);
    setAnimatedIndices(new Set());
    setTimeout(animate, 50);
  }, [animate]);

  React.useEffect(() => {
    if (triggerMode === 'manual') return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            if (triggerMode === 'entrance' && hasAnimated) return;
            if (triggerMode === 'scroll') {
              setHasAnimated(false);
              setAnimatedIndices(new Set());
            }
            setTimeout(animate, 100);
          }
        });
      },
      { threshold: scrollThreshold }
    );

    const container = containerRef.current;
    if (container) observer.observe(container);
    return () => observer.disconnect();
  }, [triggerMode, scrollThreshold, hasAnimated, animate]);

  const getCharacterStyle = (charIndex) => {
    const isAnimated = animatedIndices.has(charIndex);
    const presetConfig = getPresetConfig(charIndex, characters.length);

    const filters = [];
    if (presetConfig.blur) {
      filters.push(`blur(${isAnimated ? 0 : presetConfig.blur}px)`);
    }
    if (presetConfig.hueRotate !== undefined) {
      filters.push(`hue-rotate(${isAnimated ? 0 : presetConfig.hueRotate}deg)`);
    }
    if (presetConfig.saturation !== undefined) {
      filters.push(`saturate(${isAnimated ? 100 : presetConfig.saturation}%)`);
    }

    let transform;
    if (presetConfig.use3D) {
      const rotateX = presetConfig.rotateX || 0;
      const rotateY = presetConfig.rotateY || 0;
      const rotateZ = presetConfig.rotateZ || presetConfig.rotation || 0;
      transform = isAnimated
        ? 'translate3d(0, 0, 0) rotateX(0deg) rotateY(0deg) rotateZ(0deg) scale(1)'
        : `translate3d(${presetConfig.offsetX}px, ${presetConfig.offsetY}px, 0) rotateX(${rotateX}deg) rotateY(${rotateY}deg) rotateZ(${rotateZ}deg) scale(${presetConfig.scale})`;
    } else {
      transform = isAnimated
        ? 'translate(0, 0) rotate(0deg) scale(1)'
        : `translate(${presetConfig.offsetX}px, ${presetConfig.offsetY}px) rotate(${presetConfig.rotation}deg) scale(${presetConfig.scale})`;
    }

    return {
      display: 'inline-block',
      opacity: prefersReducedMotion ? 1 : (isAnimated ? 1 : 0),
      transform: prefersReducedMotion ? 'none' : transform,
      filter: prefersReducedMotion ? 'none' : (filters.length ? filters.join(' ') : 'none'),
      transition: prefersReducedMotion ? 'none' : `all ${animationDuration}ms ${easing}`,
      willChange: 'transform, opacity, filter',
      transformStyle: presetConfig.use3D ? 'preserve-3d' : 'flat'
    };
  };

  return (
    <div
      ref={containerRef}
      className="kinetic-typography"
      style={{
        position: 'relative',
        width: '100%',
        minHeight: '400px',
        backgroundColor: backgroundColor,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '60px 40px',
        boxSizing: 'border-box',
        overflow: 'hidden',
        perspective: '1200px'
      }}
    >
      <div
        style={{
          textAlign: textAlign,
          fontSize: `clamp(24px, ${fontSize}px, 10vw)`,
          fontWeight: fontWeight,
          letterSpacing: letterSpacing,
          color: textColor,
          fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
          lineHeight: 1.1,
          transformStyle: 'preserve-3d',
          maxWidth: '100%',
          wordBreak: 'break-word'
        }}
        aria-label={text}
      >
        {characters.map((char, index) => (
          <span
            key={index}
            style={getCharacterStyle(index)}
            aria-hidden="true"
          >
            {char.char}
          </span>
        ))}
      </div>

      {showReplayButton && (
        <button
          onClick={handleReplay}
          onMouseEnter={() => setIsButtonHovered(true)}
          onMouseLeave={() => setIsButtonHovered(false)}
          aria-label={replayButtonText}
          style={{
            marginTop: '48px',
            padding: '12px 28px',
            backgroundColor: 'transparent',
            border: `1px solid ${buttonBorderColor}`,
            borderRadius: '4px',
            color: isButtonHovered ? buttonHoverColor : buttonTextColor,
            fontSize: '13px',
            fontWeight: '400',
            letterSpacing: '0.1em',
            textTransform: 'uppercase',
            cursor: 'pointer',
            transition: 'all 300ms ease-out',
            fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
            transform: isButtonHovered ? 'translateY(-2px)' : 'translateY(0)',
            boxShadow: isButtonHovered ? '0 4px 12px rgba(0,0,0,0.3)' : 'none'
          }}
        >
          {replayButtonText}
        </button>
      )}
    </div>
  );
}

