        offsetX: (Math.sin(position * Math.PI * 3) * 30) * intensityMultiplier,
        offsetY: (Math.cos(position * Math.PI * 3) * 20) * intensityMultiplier,
        rotation: 0,
        scale: 1,
        blur: 0,
        hueRotate: position * 360,
        saturation: 150,
        staggerType: 'sequential'
      },
      wonderland: {
        offsetY: (40 + (Math.sin(charIndex * 0.5) * 40)) * intensityMultiplier,
        offsetX: (Math.sin(charIndex * 0.3) * 25) * intensityMultiplier,
        rotation: 0,
        rotateX: (35 + (Math.sin(charIndex * 0.4) * 35)) * intensityMultiplier,
        rotateY: (-40 + (Math.cos(charIndex * 0.3) * 40)) * intensityMultiplier,
        rotateZ: (-18 + (Math.sin(charIndex * 0.6) * 18)) * intensityMultiplier,
        scale: 1,
        blur: 0,
        staggerType: 'sequential',
        perspective: true,
        use3D: true
      }
    };

    return presets[preset] || presets.explosive;
  };

  // Get stagger order based on type
  const getStaggerOrder = (type, totalChars) => {
    const indices = Array.from({ length: totalChars }, (_, i) => i);
    const middle = Math.floor(totalChars / 2);

    switch (type) {
      case 'sequential':
        return indices;
      case 'reverse':
        return indices.reverse();
      case 'random':
        return indices.sort(() => Math.random() - 0.5);
      case 'fromCenter':
        return indices.sort((a, b) => 
          Math.abs(a - middle) - Math.abs(b - middle)
        );
      case 'edges':
        const left = indices.filter((_, i) => i < middle);
        const right = indices.filter((_, i) => i >= middle).reverse();
        return [...left, ...right].sort((a, b) => 
          Math.abs(a - middle) - Math.abs(b - middle)
        ).reverse();
      case 'alternating':
        const even = indices.filter(i => i % 2 === 0);
        const odd = indices.filter(i => i % 2 !== 0);
        return [...even, ...odd];
      default:
        return indices;
    }
  };

  // Animation function
  const animate = React.useCallback(() => {
    if (isAnimating || prefersReducedMotion) return;

    setIsAnimating(true);
    setAnimatedIndices(new Set());

    const chars = text.split('');
    const totalChars = chars.length;
    const presetConfig = getPresetConfig(animationPreset, 0, totalChars);
    const staggerOrder = getStaggerOrder(presetConfig.staggerType, totalChars);
    const delayIncrement = (staggerAmount * 1000) / totalChars;
    const currentDuration = animationDuration * replaySpeed;

    staggerOrder.forEach((charIndex, orderIndex) => {
      setTimeout(() => {
        setAnimatedIndices(prev => {
          const newSet = new Set(prev);
          newSet.add(charIndex);
          return newSet;
        });

        if (orderIndex === staggerOrder.length - 1) {
          setTimeout(() => {
            setIsAnimating(false);
            setHasAnimated(true);
          }, currentDuration);
        }
      }, orderIndex * delayIncrement);
    });
  }, [text, animationPreset, staggerAmount, animationDuration, replaySpeed, isAnimating, prefersReducedMotion]);

  // Intersection Observer for scroll/entrance triggers
  React.useEffect(() => {
    if (triggerMode === 'manual' || !containerRef.current) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            if (triggerMode === 'entrance' && hasAnimated) return;
            animate();
          }
        });
      },
      { threshold: scrollThreshold }
    );

    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [triggerMode, scrollThreshold, hasAnimated, animate]);

  // Manual replay handler
  const handleReplay = () => {
    setHasAnimated(false);
    animate();
  };

  // Generate character data
  const characters = text.split('').map((char, index) => {
    const presetConfig = getPresetConfig(animationPreset, index, text.length);
    const isAnimated = animatedIndices.has(index);

    // Build transform string
    let transformParts = [];

    if (presetConfig.use3D) {
      if (presetConfig.rotateX !== undefined) {
        transformParts.push(`rotateX(${isAnimated ? 0 : presetConfig.rotateX}deg)`);
      }
      if (presetConfig.rotateY !== undefined) {
        transformParts.push(`rotateY(${isAnimated ? 0 : presetConfig.rotateY}deg)`);
      }
      if (presetConfig.rotateZ !== undefined) {
        transformParts.push(`rotateZ(${isAnimated ? 0 : presetConfig.rotateZ}deg)`);
      }
      transformParts.push(
        `translate3d(${isAnimated ? 0 : presetConfig.offsetX || 0}px, ${isAnimated ? 0 : presetConfig.offsetY || 0}px, 0)`
      );
    } else {
      transformParts.push(
        `translate(${isAnimated ? 0 : presetConfig.offsetX || 0}px, ${isAnimated ? 0 : presetConfig.offsetY || 0}px)`
      );
      if (presetConfig.rotation !== undefined) {
        transformParts.push(`rotate(${isAnimated ? 0 : presetConfig.rotation}deg)`);
      }
    }

    transformParts.push(`scale(${isAnimated ? 1 : presetConfig.scale || 1})`);

    // Build filter string
    const filters = [];
    if (presetConfig.blur) {
      filters.push(`blur(${isAnimated ? 0 : presetConfig.blur}px)`);
    }
    if (presetConfig.saturation) {
      filters.push(`saturate(${isAnimated ? 100 : presetConfig.saturation}%)`);
    }
    if (presetConfig.hueRotate !== undefined) {
      filters.push(`hue-rotate(${isAnimated ? 0 : presetConfig.hueRotate}deg)`);
    }

    return {
      char: char === ' ' ? '\u00A0' : char,
      index,
      isAnimated,
      transform: transformParts.join(' '),
      filter: filters.length > 0 ? filters.join(' ') : 'none',
      needsPerspective: presetConfig.perspective,
      use3D: presetConfig.use3D
    };
  });

  const needsPerspective = characters.some(c => c.needsPerspective);

  return (
    <div
      ref={containerRef}
      className="kinetic-headline"
      style={{
        minHeight: '100vh',
        width: '100%',
        backgroundColor,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        padding: containerPadding,
        gap: '2rem',
        overflow: 'hidden'
      }}
    >
      <div
        style={{
          maxWidth: '1200px',
          width: '100%',
          textAlign: textAlign,
          ...(needsPerspective && {
            perspective: '1200px',
            transformStyle: 'preserve-3d'
          })
        }}
      >
        <h1
          style={{
            fontSize: `clamp(${fontSize * 0.5}px, ${fontSize / 16}rem + 2vw, ${fontSize * 1.5}px)`,
            fontWeight,
            letterSpacing,
            color: textColor,
            margin: 0,
            lineHeight: 1.2,
            fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
            display: 'inline-block',
            whiteSpace: 'pre-wrap',
            wordBreak: 'break-word'
          }}
        >
          {characters.map((charData) => (
            <span
              key={charData.index}
              style={{
                display: 'inline-block',
                opacity: prefersReducedMotion ? 1 : (charData.isAnimated ? 1 : 0),
                transform: prefersReducedMotion ? 'none' : charData.transform,
                filter: prefersReducedMotion ? 'none' : charData.filter,
                transition: prefersReducedMotion 
                  ? 'none' 
                  : `all ${animationDuration * replaySpeed}ms cubic-bezier(0.22, 1, 0.36, 1)`,
                willChange: 'transform, opacity, filter',
                ...(charData.use3D && {
                  transformStyle: 'preserve-3d'
                })
              }}
            >
              {charData.char}
            </span>
          ))}
        </h1>
      </div>

      {showReplayButton && (
        <button
          onClick={handleReplay}
          disabled={isAnimating}
          style={{
            padding: '0.75rem 1.5rem',
            fontSize: '0.875rem',
            fontWeight: '400',
            fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
            color: buttonTextColor,
            backgroundColor: 'transparent',
            border: `1px solid ${buttonBorderColor}`,
            borderRadius: '8px',
            cursor: isAnimating ? 'not-allowed' : 'pointer',
            opacity: isAnimating ? 0.5 : 1,
            transition: 'all 200ms ease-out',
            letterSpacing: '0.025em'
          }}
          onMouseEnter={(e) => {
            if (!isAnimating) {
              e.currentTarget.style.color = buttonHoverColor;
              e.currentTarget.style.borderColor = buttonHoverColor;
            }
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.color = buttonTextColor;
            e.currentTarget.style.borderColor = buttonBorderColor;
          }}
        >
          {replayButtonText}
        </button>
      )}
    </div>
  );
}

