      "backgroundColor": {"dataType": "color", "displayName": "Background", "defaultValue": "#F8F9FA", "group": "Colors"},
      "textColor": {"dataType": "color", "displayName": "Text Color", "defaultValue": "#212529", "group": "Colors"},
      "helixColor": {"dataType": "color", "displayName": "Helix Color", "defaultValue": "#495057", "group": "Colors"},
      "fontSize": {"dataType": "number", "displayName": "Font Size", "defaultValue": 60, "group": "Typography"},
      "fontWeight": {"dataType": "select", "displayName": "Weight", "defaultValue": "400", "options": ["300", "400", "500"], "group": "Typography"}
    }
  }
};

function Component({ config = {} }) {
  const text = config?.text || "GENETIC CODE";
  const showReplayButton = config?.showReplayButton !== false;
  const triggerMode = config?.triggerMode || "entrance";
  const helixTurns = parseInt(config?.helixTurns || "3");
  const spiralDuration = parseInt(config?.spiralDuration || "1800");
  const backgroundColor = config?.backgroundColor || "#F8F9FA";
  const textColor = config?.textColor || "#212529";
  const helixColor = config?.helixColor || "#495057";
  const fontSize = parseInt(config?.fontSize || "60");
  const fontWeight = config?.fontWeight || "400";

  const containerRef = React.useRef(null);
  const [animatedIndices, setAnimatedIndices] = React.useState(new Set());
  const [hasAnimated, setHasAnimated] = React.useState(false);

  const prefersReducedMotion = typeof window !== 'undefined' ? window.matchMedia('(prefers-reduced-motion: reduce)').matches : false;

  const characters = text.split('').map((char, idx) => ({ char: char === ' ' ? '\u00A0' : char, index: idx }));

  const animate = React.useCallback(() => {
    if (prefersReducedMotion) {
      setAnimatedIndices(new Set(characters.map((_, i) => i)));
      setHasAnimated(true);
      return;
    }

    setAnimatedIndices(new Set());
    const delayPerChar = spiralDuration / characters.length;

    characters.forEach((_, idx) => {
      setTimeout(() => {
        setAnimatedIndices(prev => new Set([...prev, idx]));
      }, idx * delayPerChar);
    });

    setHasAnimated(true);
  }, [characters, spiralDuration, prefersReducedMotion]);

  const handleReplay = () => {
    setHasAnimated(false);
    setAnimatedIndices(new Set());
    setTimeout(animate, 50);
  };

  React.useEffect(() => {
    if (triggerMode === 'manual') return;
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            if (triggerMode === 'entrance' && hasAnimated) return;
            animate();
          }
        });
      },
      { threshold: 0.3 }
    );
    if (containerRef.current) observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [triggerMode, hasAnimated, animate]);

  const getHelixTransform = (idx, isAnimated) => {
    const position = idx / characters.length;
    const angle = position * Math.PI * 2 * helixTurns;
    const radius = 200;

    if (!isAnimated) {
      const x = Math.cos(angle) * radius;
      const y = Math.sin(angle) * radius + position * -100;
      return `translate(${x}px, ${y}px) rotate(${angle * 180 / Math.PI}deg) scale(0.5)`;
    }
    return 'translate(0, 0) rotate(0) scale(1)';
  };

  return (
    <div ref={containerRef} className="dna-helix-spiral" style={{
      position: 'relative', width: '100%', minHeight: '400px', backgroundColor,
      display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
      padding: '60px 40px', overflow: 'hidden'
    }}>
      <div style={{ position: 'relative', perspective: '1000px', transformStyle: 'preserve-3d' }}>
        {characters.map((item, idx) => {
          const isAnimated = animatedIndices.has(idx);
          return (
            <span key={idx} style={{
              display: 'inline-block',
              fontSize: `${fontSize}px`,
              fontWeight,
              color: textColor,
              opacity: prefersReducedMotion ? 1 : (isAnimated ? 1 : 0),
              transform: prefersReducedMotion ? 'none' : getHelixTransform(idx, isAnimated),
              transition: `all ${spiralDuration * 0.001}s cubic-bezier(0.34, 1.56, 0.64, 1)`,
              willChange: 'transform, opacity'
            }}>
              {item.char}
            </span>
          );
        })}
      </div>
      {showReplayButton && (
        <button onClick={handleReplay} style={{
          position: 'absolute', bottom: '40px', padding: '12px 28px', backgroundColor: 'transparent',
          border: `1px solid ${textColor}40`, borderRadius: '4px', color: textColor,
          fontSize: '13px', fontWeight: '400', letterSpacing: '0.1em', textTransform: 'uppercase',
          cursor: 'pointer', transition: 'all 300ms ease', opacity: 0.6
        }} onMouseEnter={(e) => e.target.style.opacity = '1'} onMouseLeave={(e) => e.target.style.opacity = '0.6'}>
          Replay
        </button>
      )}
    </div>
  );
}

