  "editorElement": {
    "selector": ".neon-flicker",
    "displayName": "Neon Flicker",
    "archetype": "container",
    "data": {
      "text": {
        "dataType": "text",
        "displayName": "Text Content",
        "defaultValue": "NEON NIGHTS",
        "group": "Content"
      },
      "showReplayButton": {
