  const [hasAnimated, setHasAnimated] = React.useState(false);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const animate = React.useCallback(() => {
    if (prefersReducedMotion) {
      setIsAnimating(true);
      setHasAnimated(true);
      return;
    }

    setIsAnimating(true);
    setHasAnimated(true);

    // Animation implementation would go here
    setTimeout(() => {
      setIsAnimating(false);
    }, 2000);
  }, [prefersReducedMotion]);

  const handleReplay = () => {
    setHasAnimated(false);
    setIsAnimating(false);
    setTimeout(animate, 50);
  };

  React.useEffect(() => {
    if (triggerMode === 'manual') return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            if (triggerMode === 'entrance' && hasAnimated) return;
            animate();
          }
        });
      },
      { threshold: 0.3 }
    );

    if (containerRef.current) {
      observer.observe(containerRef.current);
    }

    return () => observer.disconnect();
  }, [triggerMode, hasAnimated, animate]);

  return (
    <div
      ref={containerRef}
      className="vaporwave"
      style={{
        position: 'relative',
        width: '100%',
        minHeight: '400px',
        backgroundColor,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '60px 40px',
        overflow: 'hidden'
      }}
    >
      <div
        style={{
          fontSize: `clamp(32px, ${fontSize}px, 10vw)`,
          fontWeight,
          color: textColor,
          textAlign: 'center',
          opacity: isAnimating || hasAnimated ? 1 : 0,
          transition: 'opacity 300ms ease'
        }}
      >
        {text}
      </div>

      {showReplayButton && (
        <button
          onClick={handleReplay}
          style={{
            position: 'absolute',
            bottom: '40px',
            padding: '12px 28px',
            backgroundColor: 'transparent',
            border: `1px solid ${textColor}40`,
            borderRadius: '4px',
            color: textColor,
            fontSize: '13px',
            fontWeight: '400',
            letterSpacing: '0.1em',
            textTransform: 'uppercase',
            cursor: 'pointer',
            transition: 'all 300ms ease',
            opacity: 0.6
          }}
          onMouseEnter={(e) => e.target.style.opacity = '1'}
          onMouseLeave={(e) => e.target.style.opacity = '0.6'}
        >
          Replay
        </button>
      )}
    </div>
  );
}

