        "defaultValue": "300",
        "options": ["200", "250", "300", "350", "400"],
        "group": "Animation",
        "description": "Distance from cursor for effect"
      },
      "minWeight": {
        "dataType": "select",
        "displayName": "Minimum Font Weight",
        "defaultValue": "300",
        "options": ["100", "200", "300", "400"],
        "group": "Typography"
      },
      "maxWeight": {
        "dataType": "select",
        "displayName": "Maximum Font Weight",
