  const iconType = config?.iconType || "star";
  const customImageUrl = config?.customImageUrl || "";
  const iconVerticalOffset = parseInt(config?.iconVerticalOffset || "0");
  const iconPlacementMode = config?.iconFrequency || "random";
  const iconFrequencyAmount = config?.iconFrequencyAmount || "medium";
  const iconPositions = config?.iconPositions || "";
  const animateOnLoad = config?.animateOnLoad !== false;
  const showHoverEffect = config?.showHoverEffect !== false;
  const fontSize = parseInt(config?.fontSize || "48");
  const fontWeight = config?.fontWeight || "400";
  const letterSpacing = config?.letterSpacing || "0.025em";
