  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const textColor = config?.textColor || "#212529";
  const iconColor = config?.iconColor || "#495057";
  const iconHoverColor = config?.iconHoverColor || "#212529";
  const iconBackgroundColor = config?.iconBackgroundColor || "transparent";
  const iconBackgroundPadding = parseInt(config?.iconBackgroundPadding || "0");
  const iconSize = parseInt(config?.iconSize || "32");
  const paddingV = config?.paddingVertical || "80px";
  const paddingH = config?.paddingHorizontal || "40px";
  const maxWidth = config?.maxWidth || "1200px";

  // Check for reduced motion preference
  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  // Icon frequency percentages (for random mode)
  const frequencyMap = {
    low: 0.2,
    medium: 0.4,
    high: 0.6
  };

  const iconChance = frequencyMap[iconFrequencyAmount];

  // Parse specific icon positions (for specific mode)
  const specificPositions = iconPositions
    ? iconPositions.split(',').map(pos => parseInt(pos.trim())).filter(pos => !isNaN(pos) && pos > 0)
    : [];

  // Create a Set for O(1) lookup
  const specificPositionsSet = new Set(specificPositions);

