                    : `translateY(${iconVerticalOffset}px) scale(${isHovered && showHoverEffect ? 1.1 : 1})`,
                  transition: shouldAnimate
                    ? `opacity 400ms ease-out ${staggerDelay}ms, transform 400ms ease-out ${staggerDelay}ms, color 200ms ease-out, background-color 200ms ease-out`
                    : 'transform 200ms ease-out, color 200ms ease-out, background-color 200ms ease-out',
                  cursor: showHoverEffect ? 'pointer' : 'default',
                  willChange: 'transform, opacity',
                  lineHeight: 1
                }}
                onMouseEnter={() => showHoverEffect && setIsHovered(true)}
                onMouseLeave={() => showHoverEffect && setIsHovered(false)}
              >
                {iconType === 'custom' && currentImageUrl ? (
                  <img 
                    src={currentImageUrl} 
                    alt="" 
                    style={{
                      width: `${iconSize}px`,
                      height: `${iconSize}px`,
                      display: 'block',
                      objectFit: 'contain'
                    }}
                  />
                ) : (
                  <span style={{ fontSize: `${iconSize}px`, lineHeight: 1, display: 'flex' }}>
                    {getIconSVG(currentIconType)}
                  </span>
                )}
              </span>
            );
          }
        })}
      </div>
    </div>
  );
}

