function Component({ config = {} }) {
  const text = config?.text || "The art of typography is the art of creating harmony and clarity through the careful arrangement of letterforms.";
  const animationType = config?.animationType || "typewriter";
  const showCursor = config?.showCursor !== false;
  const cursorStyle = config?.cursorStyle || "line";
  const typingSpeed = parseInt(config?.typingSpeed || "80");
  const speedVariation = config?.speedVariation !== false;
  const startDelay = parseInt(config?.startDelay || "500");
  const autoStart = config?.autoStart !== false;
  const visibilityThreshold = parseFloat(config?.visibilityThreshold || "0.2");
  const repeatAnimation = config?.repeatAnimation === true;
  const fontSize = config?.fontSize || 32;
  const fontWeight = config?.fontWeight || "400";
  const fontFamily = config?.fontFamily || "sans-serif";
  const textAlign = config?.textAlign || "left";
  const lineHeight = config?.lineHeight || "1.6";
  const textColor = config?.textColor || "#212529";
  const cursorColor = config?.cursorColor || "#495057";
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const containerPadding = config?.containerPadding || "60";
  const maxWidth = config?.maxWidth || "800";

  const [displayedText, setDisplayedText] = React.useState("");
  const [isTyping, setIsTyping] = React.useState(false);
  const [showCursorBlink, setShowCursorBlink] = React.useState(true);
  const [prefersReducedMotion, setPrefersReducedMotion] = React.useState(false);
  const containerRef = React.useRef(null);
  const typingTimeoutRef = React.useRef(null);

  // Check for reduced motion preference
  React.useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(mediaQuery.matches);

    const handleChange = (e) => setPrefersReducedMotion(e.matches);
    mediaQuery.addEventListener('change', handleChange);
    return () => mediaQuery.removeEventListener('change', handleChange);
  }, []);

  // Typing animation logic
  const startTyping = React.useCallback(() => {
    if (prefersReducedMotion) {
      setDisplayedText(text);
      setShowCursorBlink(false);
      return;
    }

    setDisplayedText("");
    setIsTyping(true);
    setShowCursorBlink(animationType === 'typewriter' && showCursor);

    let currentIndex = 0;

    const typeNextCharacter = () => {
      if (currentIndex < text.length) {
        setDisplayedText(text.substring(0, currentIndex + 1));
        currentIndex++;

        // Calculate delay with variation
        let delay = typingSpeed;
        if (speedVariation && animationType === 'typewriter') {
          const char = text[currentIndex - 1];
          if (char === ' ') {
            delay = typingSpeed * 0.5;
          } else if (['.', ',', '!', '?', ';', ':'].includes(char)) {
            delay = typingSpeed * 1.5;
          } else {
            delay = typingSpeed + (Math.random() * 30 - 15);
          }
        }

        typingTimeoutRef.current = setTimeout(typeNextCharacter, delay);
      } else {
        setIsTyping(false);
        if (animationType === 'typewriter') {
          setTimeout(() => setShowCursorBlink(false), 400);
        }
      }
    };

    typingTimeoutRef.current = setTimeout(typeNextCharacter, startDelay);
  }, [text, animationType, typingSpeed, speedVariation, startDelay, prefersReducedMotion, showCursor]);

  // Scramble animation logic
  const startScramble = React.useCallback(() => {
    if (prefersReducedMotion) {
      setDisplayedText(text);
      return;
    }

    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*';
    setIsTyping(true);

    let iterations = 0;
    const maxIterations = text.length;

    const scrambleInterval = setInterval(() => {
      setDisplayedText(current => 
        text.split('').map((char, index) => {
          if (index < iterations) {
            return text[index];
          }
          if (char === ' ') return ' ';
          return chars[Math.floor(Math.random() * chars.length)];
        }).join('')
      );

      iterations += 1 / 3;

      if (iterations >= maxIterations) {
        clearInterval(scrambleInterval);
        setDisplayedText(text);
        setIsTyping(false);
      }
    }, typingSpeed);

    return () => clearInterval(scrambleInterval);
  }, [text, typingSpeed, prefersReducedMotion]);

  // Decode animation (progressive character resolution from random to correct)
  const startDecode = React.useCallback(() => {
    if (prefersReducedMotion) {
      setDisplayedText(text);
      return;
    }

    const chars = '01';
    setIsTyping(true);
    setDisplayedText(text.split('').map(c => c === ' ' ? ' ' : chars[Math.floor(Math.random() * 2)]).join(''));

    let resolvedCount = 0;
    const decodeInterval = setInterval(() => {
      if (resolvedCount >= text.length) {
        clearInterval(decodeInterval);
        setDisplayedText(text);
        setIsTyping(false);
        return;
      }

      setDisplayedText(current => {
        const chars_array = current.split('');
        const unresolved = [];

        chars_array.forEach((char, i) => {
          if (i >= resolvedCount && text[i] !== ' ' && char !== text[i]) {
            unresolved.push(i);
          }
        });

        if (unresolved.length > 0 && Math.random() < 0.3) {
          const indexToResolve = unresolved[Math.floor(Math.random() * unresolved.length)];
          chars_array[indexToResolve] = text[indexToResolve];
          resolvedCount++;
        }

        unresolved.forEach(i => {
          if (chars_array[i] !== text[i]) {
            chars_array[i] = chars[Math.floor(Math.random() * 2)];
          }
        });

        return chars_array.join('');
      });
    }, typingSpeed);

    return () => clearInterval(decodeInterval);
  }, [text, typingSpeed, prefersReducedMotion]);

  // Start animation based on type
  const startAnimation = React.useCallback(() => {
    if (animationType === 'typewriter') {
      startTyping();
    } else if (animationType === 'scramble') {
      startScramble();
    } else if (animationType === 'decode') {
      startDecode();
    } else {
      // For CSS-based animations, just show the text
      setDisplayedText(text);
      setIsTyping(false);
    }
  }, [animationType, startTyping, startScramble, startDecode, text]);

  // Intersection Observer for scroll-triggered animation
  React.useEffect(() => {
    if (!autoStart) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            startAnimation();
            if (!repeatAnimation) {
              observer.unobserve(entry.target);
            }
          } else if (repeatAnimation) {
            if (typingTimeoutRef.current) {
              clearTimeout(typingTimeoutRef.current);
            }
            setDisplayedText("");
            setIsTyping(false);
          }
        });
      },
      { threshold: visibilityThreshold }
    );

    if (containerRef.current) {
      observer.observe(containerRef.current);
    }

    return () => {
      observer.disconnect();
      if (typingTimeoutRef.current) {
        clearTimeout(typingTimeoutRef.current);
      }
    };
  }, [autoStart, visibilityThreshold, repeatAnimation, startAnimation]);

  // Font family mapping
  const getFontFamily = () => {
    if (fontFamily === 'monospace') {
      return '"Monaco", "Courier New", monospace';
    } else if (fontFamily === 'serif') {
      return 'Georgia, "Times New Roman", serif';
    }
    return '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
  };

  // Cursor style mapping
  const getCursorCharacter = () => {
    if (cursorStyle === 'block') return '█';
    if (cursorStyle === 'underscore') return '_';
    return '|';
  };

  return (
    <div 
      ref={containerRef}
      className="typewriter-animation"
      style={{
        backgroundColor,
        padding: `${containerPadding}px 20px`,
        minHeight: '200px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: textAlign === 'center' ? 'center' : textAlign === 'right' ? 'flex-end' : 'flex-start'
      }}
    >
      <div
        style={{
          fontSize: `${fontSize}px`,
          fontWeight,
          fontFamily: getFontFamily(),
          textAlign,
          lineHeight,
          color: textColor,
          maxWidth: maxWidth === '100%' ? '100%' : `${maxWidth}px`,
          width: '100%',
          position: 'relative'
        }}
      >
        {/* Typewriter, Scramble, and Decode animations */}
        {['typewriter', 'scramble', 'decode'].includes(animationType) && (
          <>
            {displayedText}
            {showCursor && showCursorBlink && animationType === 'typewriter' && (
              <span
                style={{
                  color: cursorColor,
                  marginLeft: cursorStyle === 'underscore' ? '0' : '2px',
                  animation: 'cursorBlink 1.06s ease-in-out infinite',
                  display: 'inline-block'
                }}
              >
                {getCursorCharacter()}
              </span>
            )}
          </>
        )}

        {/* CSS-based animations - triggered after initial render */}
        {['glitch-reveal', 'reveal-wave', 'fade-chars', 'slide-chars'].includes(animationType) && (
          <div style={{ position: 'relative', overflow: animationType === 'reveal-wave' || animationType === 'slide-chars' ? 'clip' : 'visible' }}>
            {text.split('').map((char, index) => {
              const animationName = 
                animationType === 'glitch-reveal' ? 'glitchReveal' :
                animationType === 'reveal-wave' ? 'revealWave' :
                animationType === 'fade-chars' ? 'fadeChar' : 'slideChar';

              const duration = 
                animationType === 'glitch-reveal' ? '0.6s' :
                animationType === 'reveal-wave' ? '0.5s' :
                animationType === 'fade-chars' ? '0.4s' : '0.5s';

              const delayMultiplier = 
                animationType === 'glitch-reveal' ? 30 :
                animationType === 'reveal-wave' ? 25 :
                animationType === 'fade-chars' ? 40 : 30;

              return (
                <span
                  key={index}
                  style={{
                    display: 'inline-block',
                    opacity: 0,
                    animation: displayedText ? `${animationName} ${duration} ease-out ${index * delayMultiplier}ms forwards` : 'none'
                  }}
                >
                  {char === ' ' ? '\u00A0' : char}
                </span>
              );
            })}
          </div>
        )}

        <style>{`
          @keyframes cursorBlink {
            0%, 49% { opacity: 1; }
            50%, 100% { opacity: 0; }
          }

          @keyframes glitchReveal {
            0% {
              opacity: 0;
              transform: translateX(-10px) skewX(-10deg);
              filter: blur(4px);
            }
            60% {
              opacity: 1;
              transform: translateX(3px) skewX(5deg);
            }
            100% {
              opacity: 1;
              transform: translateX(0) skewX(0);
              filter: blur(0);
            }
          }

          @keyframes revealWave {
            0% {
              opacity: 0;
              transform: translateY(20px) scale(0.8);
            }
            50% {
              transform: translateY(-5px) scale(1.05);
            }
            100% {
              opacity: 1;
              transform: translateY(0) scale(1);
            }
          }

          @keyframes fadeChar {
            0% {
              opacity: 0;
            }
            100% {
              opacity: 1;
            }
          }

          @keyframes slideChar {
            0% {
              opacity: 0;
              transform: translateX(-15px);
            }
            100% {
              opacity: 1;
              transform: translateX(0);
            }
          }

          @media (prefers-reduced-motion: reduce) {
            @keyframes cursorBlink {
              0%, 100% { opacity: 1; }
            }
            @keyframes glitchReveal,
            @keyframes revealWave,
            @keyframes fadeChar,
            @keyframes slideChar {
              0%, 100% {
                opacity: 1;
                transform: none;
                filter: none;
              }
            }
          }
        `}</style>
      </div>
    </div>
  );
}

