function Component({ config = {} }) {
  const containerRef = React.useRef(null);
  const canvasRef = React.useRef(null);
  const [threeLoaded, setThreeLoaded] = React.useState(false);
  const [currentPreset, setCurrentPreset] = React.useState(config?.preset || 'quantum_grid');
  const sceneRef = React.useRef(null);

  // Load Three.js - ONLY library we use
  React.useEffect(() => {
    if (typeof THREE !== 'undefined') {
      setThreeLoaded(true);
      return;
    }

    const script = document.createElement('script');
    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js';
    script.async = true;
    script.onload = () => setThreeLoaded(true);
    document.head.appendChild(script);

    return () => {
      if (script.parentNode) {
        script.parentNode.removeChild(script);
      }
    };
  }, []);

  // Sync preset from config
  React.useEffect(() => {
    if (config?.preset) {
      setCurrentPreset(config.preset);
    }
  }, [config?.preset]);

  // Preset configurations
  const presetConfigs = {
    quantum_grid: {
      name: 'Quantum Grid',
      description: 'Warping energy grid with gravity wells'
    },
    neural_network: {
      name: 'Neural Network',
      description: 'Connected nodes forming neural pathways'
    },
    holographic_scan: {
      name: 'Holographic Scan',
      description: 'Scanning holographic display lines'
    },
    data_stream: {
      name: 'Data Stream',
      description: 'Flowing binary data particles'
    },
    energy_field: {
      name: 'Energy Field',
      description: 'Pulsing electromagnetic fields'
    },
    particle_cloud: {
      name: 'Particle Cloud',
      description: 'Swirling particle vortex'
    },
    geometric_pulse: {
      name: 'Geometric Pulse',
      description: 'Expanding geometric patterns'
    },
    cyber_matrix: {
      name: 'Cyber Matrix',
      description: 'Matrix-style falling code'
    }
  };

  // Initialize Three.js scene
  React.useEffect(() => {
    if (!threeLoaded || !containerRef.current) return;

    const width = containerRef.current.clientWidth;
    const height = containerRef.current.clientHeight;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 1000);
    camera.position.z = 250;
    camera.position.y = 30;

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
      canvas: canvasRef.current
    });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

    const intensityMap = { 'subtle': 0.5, 'medium': 1.0, 'intense': 1.5 };
    const intensity = intensityMap[config?.effectIntensity || 'medium'] || 1.0;
    const speed = parseFloat(config?.animationSpeed || '1.0');

    // Create scene objects based on preset
    let sceneObjects = [];
    const mouse = { x: 0, y: 0 };
    let time = 0;

    const createQuantumGrid = () => {
      const gridGeometry = new THREE.PlaneGeometry(400, 400, 50, 50);
      const gridMaterial = new THREE.MeshBasicMaterial({
        color: new THREE.Color(config?.accentColor1 || '#00D9FF'),
        wireframe: true,
        transparent: true,
        opacity: 0.3,
        blending: THREE.AdditiveBlending
      });
      const grid = new THREE.Mesh(gridGeometry, gridMaterial);
      grid.rotation.x = -Math.PI / 2;
      grid.position.y = -40;
      scene.add(grid);

      const originalPositions = gridGeometry.attributes.position.array.slice();
      sceneObjects.push({ grid, originalPositions, type: 'quantum_grid' });
    };

    const createNeuralNetwork = () => {
      const nodeCount = 30;
      const nodes = [];

      for (let i = 0; i < nodeCount; i++) {
        const nodeGeometry = new THREE.SphereGeometry(2, 8, 8);
        const nodeMaterial = new THREE.MeshBasicMaterial({
          color: new THREE.Color(config?.accentColor2 || '#6366F1'),
          transparent: true,
          opacity: 0.8
        });
        const node = new THREE.Mesh(nodeGeometry, nodeMaterial);
        node.position.set(
          (Math.random() - 0.5) * 200,
          (Math.random() - 0.5) * 100,
          (Math.random() - 0.5) * 200
        );
        scene.add(node);
        nodes.push(node);
      }

      // Connection lines
      const lineGeometry = new THREE.BufferGeometry();
      const linePositions = [];
      for (let i = 0; i < nodeCount; i++) {
        for (let j = i + 1; j < nodeCount; j++) {
          if (Math.random() > 0.9) {
            linePositions.push(nodes[i].position.x, nodes[i].position.y, nodes[i].position.z);
            linePositions.push(nodes[j].position.x, nodes[j].position.y, nodes[j].position.z);
          }
        }
      }
      lineGeometry.setAttribute('position', new THREE.Float32BufferAttribute(linePositions, 3));
      const lineMaterial = new THREE.LineBasicMaterial({
        color: new THREE.Color(config?.accentColor1 || '#00D9FF'),
        transparent: true,
        opacity: 0.2
      });
      const lines = new THREE.LineSegments(lineGeometry, lineMaterial);
      scene.add(lines);

      sceneObjects.push({ nodes, lines, type: 'neural_network' });
    };

    const createHolographicScan = () => {
      for (let i = 0; i < 20; i++) {
        const lineGeometry = new THREE.PlaneGeometry(300, 2, 1, 1);
        const lineMaterial = new THREE.MeshBasicMaterial({
          color: new THREE.Color(config?.accentColor1 || '#00D9FF'),
          transparent: true,
          opacity: 0.3,
          blending: THREE.AdditiveBlending
        });
        const line = new THREE.Mesh(lineGeometry, lineMaterial);
        line.position.y = -100 + i * 10;
        scene.add(line);
        sceneObjects.push({ line, startY: line.position.y, type: 'holographic_scan' });
      }
    };

    const createDataStream = () => {
      const particleDensityMap = { 'low': 500, 'medium': 1000, 'high': 2000 };
      const particleCount = particleDensityMap[config?.particleDensity || 'medium'] || 1000;

      const geometry = new THREE.BufferGeometry();
      const positions = new Float32Array(particleCount * 3);
      const velocities = [];

      for (let i = 0; i < particleCount; i++) {
        positions[i * 3] = (Math.random() - 0.5) * 400;
        positions[i * 3 + 1] = Math.random() * 200 - 100;
        positions[i * 3 + 2] = (Math.random() - 0.5) * 200;
        velocities.push(Math.random() * 2 + 1);
      }

      geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

      const material = new THREE.PointsMaterial({
        size: 2,
        color: new THREE.Color(config?.accentColor3 || '#8B5CF6'),
        transparent: true,
        opacity: 0.6,
        blending: THREE.AdditiveBlending
      });

      const particles = new THREE.Points(geometry, material);
      scene.add(particles);

      sceneObjects.push({ particles, velocities, type: 'data_stream' });
    };

    const createEnergyField = () => {
      for (let i = 0; i < 5; i++) {
        const ringGeometry = new THREE.RingGeometry(20 + i * 20, 22 + i * 20, 32);
        const ringMaterial = new THREE.MeshBasicMaterial({
          color: new THREE.Color(config?.accentColor4 || '#10B981'),
          transparent: true,
          opacity: 0.3 - i * 0.05,
          side: THREE.DoubleSide,
          blending: THREE.AdditiveBlending
        });
        const ring = new THREE.Mesh(ringGeometry, ringMaterial);
        ring.position.y = 0;
        scene.add(ring);
        sceneObjects.push({ ring, index: i, type: 'energy_field' });
      }
    };

    const createParticleCloud = () => {
      const particleCount = 2000;
      const geometry = new THREE.BufferGeometry();
      const positions = new Float32Array(particleCount * 3);
      const angles = [];
      const radii = [];

      for (let i = 0; i < particleCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const radius = Math.random() * 100 + 50;
        positions[i * 3] = Math.cos(angle) * radius;
        positions[i * 3 + 1] = (Math.random() - 0.5) * 100;
        positions[i * 3 + 2] = Math.sin(angle) * radius;
        angles.push(angle);
        radii.push(radius);
      }

      geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

      const material = new THREE.PointsMaterial({
        size: 2,
        color: new THREE.Color(config?.accentColor2 || '#6366F1'),
        transparent: true,
        opacity: 0.6,
        blending: THREE.AdditiveBlending
      });

      const particles = new THREE.Points(geometry, material);
      scene.add(particles);

      sceneObjects.push({ particles, angles, radii, type: 'particle_cloud' });
    };

    const createGeometricPulse = () => {
      for (let i = 0; i < 3; i++) {
        const geometry = new THREE.BoxGeometry(40, 40, 40);
        const material = new THREE.MeshBasicMaterial({
          color: new THREE.Color(config?.accentColor1 || '#00D9FF'),
          wireframe: true,
          transparent: true,
          opacity: 0.4
        });
        const cube = new THREE.Mesh(geometry, material);
        scene.add(cube);
        sceneObjects.push({ cube, index: i, type: 'geometric_pulse' });
      }
    };

    const createCyberMatrix = () => {
      const columns = 30;
      const drops = [];

      for (let i = 0; i < columns; i++) {
        const lineGeometry = new THREE.PlaneGeometry(8, 200, 1, 1);
        const lineMaterial = new THREE.MeshBasicMaterial({
          color: new THREE.Color(config?.accentColor4 || '#10B981'),
          transparent: true,
          opacity: 0.5,
          blending: THREE.AdditiveBlending
        });
        const line = new THREE.Mesh(lineGeometry, lineMaterial);
        line.position.x = (i - columns / 2) * 15;
        line.position.y = Math.random() * 200;
        scene.add(line);
        drops.push({ line, speed: Math.random() * 2 + 1 });
      }

      sceneObjects.push({ drops, type: 'cyber_matrix' });
    };

    // Initialize current preset
    const initializePreset = (preset) => {
      // Clear previous objects
      sceneObjects.forEach(obj => {
        if (obj.grid) scene.remove(obj.grid);
        if (obj.nodes) obj.nodes.forEach(n => scene.remove(n));
        if (obj.lines) scene.remove(obj.lines);
        if (obj.line) scene.remove(obj.line);
        if (obj.particles) scene.remove(obj.particles);
        if (obj.ring) scene.remove(obj.ring);
        if (obj.cube) scene.remove(obj.cube);
        if (obj.drops) obj.drops.forEach(d => scene.remove(d.line));
      });
      sceneObjects = [];

      switch (preset) {
        case 'quantum_grid':
          createQuantumGrid();
          break;
        case 'neural_network':
          createNeuralNetwork();
          break;
        case 'holographic_scan':
          createHolographicScan();
          break;
        case 'data_stream':
          createDataStream();
          break;
        case 'energy_field':
          createEnergyField();
          break;
        case 'particle_cloud':
          createParticleCloud();
          break;
        case 'geometric_pulse':
          createGeometricPulse();
          break;
        case 'cyber_matrix':
          createCyberMatrix();
          break;
      }
    };

    initializePreset(currentPreset);

    const onMouseMove = (event) => {
      if (config?.enableInteraction === false) return;
      const rect = containerRef.current.getBoundingClientRect();
      mouse.x = ((event.clientX - rect.left) / width) * 2 - 1;
      mouse.y = -((event.clientY - rect.top) / height) * 2 + 1;
    };

    const onResize = () => {
      if (!containerRef.current) return;
      const newWidth = containerRef.current.clientWidth;
      const newHeight = containerRef.current.clientHeight;
      camera.aspect = newWidth / newHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(newWidth, newHeight);
    };

    containerRef.current.addEventListener('mousemove', onMouseMove);
    window.addEventListener('resize', onResize);

    const animate = () => {
      const animationId = requestAnimationFrame(animate);
      time += 0.01 * speed;

      sceneObjects.forEach(obj => {
        if (obj.type === 'quantum_grid' && obj.grid) {
          const positions = obj.grid.geometry.attributes.position;
          for (let i = 0; i < positions.count; i++) {
            const x = obj.originalPositions[i * 3];
            const z = obj.originalPositions[i * 3 + 2];
            let y = Math.sin(x * 0.05 + time) * Math.cos(z * 0.05 + time) * 8 * intensity;

            if (config?.enableInteraction !== false) {
              const worldMouse = new THREE.Vector3(mouse.x * 200, 0, mouse.y * 200);
              const dx = x - worldMouse.x;
              const dz = z - worldMouse.z;
              const dist = Math.sqrt(dx * dx + dz * dz);
              if (dist < 100) {
                const force = (100 - dist) / 100;
                y -= force * 30 * intensity;
              }
            }
            positions.setY(i, y);
          }
          positions.needsUpdate = true;
        }

        if (obj.type === 'neural_network' && obj.nodes) {
          obj.nodes.forEach((node, i) => {
            node.position.y += Math.sin(time + i) * 0.2 * intensity;
            node.rotation.y += 0.01 * speed;
          });
        }

        if (obj.type === 'holographic_scan' && obj.line) {
          obj.line.position.y = obj.startY + Math.sin(time * 2 + obj.startY * 0.1) * 20 * intensity;
        }

        if (obj.type === 'data_stream' && obj.particles) {
          const positions = obj.particles.geometry.attributes.position.array;
          for (let i = 0; i < obj.velocities.length; i++) {
            positions[i * 3 + 1] += obj.velocities[i] * speed * intensity;
            if (positions[i * 3 + 1] > 100) {
              positions[i * 3 + 1] = -100;
            }
          }
          obj.particles.geometry.attributes.position.needsUpdate = true;
        }

        if (obj.type === 'energy_field' && obj.ring) {
          obj.ring.rotation.z += 0.005 * speed * (obj.index + 1);
          obj.ring.scale.set(
            1 + Math.sin(time + obj.index) * 0.1 * intensity,
            1 + Math.sin(time + obj.index) * 0.1 * intensity,
            1
          );
        }

        if (obj.type === 'particle_cloud' && obj.particles) {
          const positions = obj.particles.geometry.attributes.position.array;
          for (let i = 0; i < obj.angles.length; i++) {
            obj.angles[i] += 0.01 * speed;
            positions[i * 3] = Math.cos(obj.angles[i]) * obj.radii[i];
            positions[i * 3 + 2] = Math.sin(obj.angles[i]) * obj.radii[i];
          }
          obj.particles.geometry.attributes.position.needsUpdate = true;
          obj.particles.rotation.y += 0.002 * speed;
        }

        if (obj.type === 'geometric_pulse' && obj.cube) {
          const scale = 1 + Math.sin(time * 2 + obj.index) * 0.3 * intensity;
          obj.cube.scale.set(scale, scale, scale);
          obj.cube.rotation.x += 0.01 * speed;
          obj.cube.rotation.y += 0.015 * speed;
        }

        if (obj.type === 'cyber_matrix' && obj.drops) {
          obj.drops.forEach(drop => {
            drop.line.position.y -= drop.speed * speed * intensity;
            if (drop.line.position.y < -100) {
              drop.line.position.y = 200;
            }
          });
        }
      });

      // Camera movement
      if (config?.enableInteraction !== false) {
        camera.position.x += (mouse.x * 20 - camera.position.x) * 0.03;
        camera.position.y += (30 - mouse.y * 15 - camera.position.y) * 0.03;
      }
      camera.lookAt(0, 0, 0);

      renderer.render(scene, camera);

      sceneRef.current = { animationId, sceneObjects };
    };

    animate();

    sceneRef.current = { 
      scene, 
      camera, 
      renderer, 
      sceneObjects,
      initializePreset 
    };

    return () => {
      if (sceneRef.current?.animationId) {
        cancelAnimationFrame(sceneRef.current.animationId);
      }
      containerRef.current?.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('resize', onResize);

      sceneObjects.forEach(obj => {
        if (obj.grid) {
          obj.grid.geometry.dispose();
          obj.grid.material.dispose();
        }
        if (obj.particles) {
          obj.particles.geometry.dispose();
          obj.particles.material.dispose();
        }
      });
      renderer.dispose();
    };
  }, [threeLoaded, currentPreset, config?.enableInteraction, config?.effectIntensity, config?.animationSpeed, config?.particleDensity, config?.accentColor1, config?.accentColor2, config?.accentColor3, config?.accentColor4]);

  // Handle preset change
  React.useEffect(() => {
    if (sceneRef.current?.initializePreset) {
      sceneRef.current.initializePreset(currentPreset);
    }
  }, [currentPreset]);

  const prefersReducedMotion = typeof window !== 'undefined' 
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches 
    : false;

  return (
    <div
      ref={containerRef}
      className="futuristic-text-container"
      style={{
        position: 'relative',
        width: '100%',
        height: '100vh',
        backgroundColor: config?.backgroundColor || '#0A0A0F',
        overflow: 'hidden',
        fontFamily: 'system-ui, -apple-system, sans-serif'
      }}
    >
      <canvas
        ref={canvasRef}
        style={{
          display: 'block',
          width: '100%',
          height: '100%',
          opacity: prefersReducedMotion ? 0.5 : 1,
          transition: 'opacity 600ms ease-out'
        }}
      />

      {!threeLoaded && (
        <div style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          color: config?.textColor || '#E8E9ED',
          fontSize: '16px',
          fontWeight: '300',
          letterSpacing: '0.15em',
          textTransform: 'uppercase'
        }}>
          Initializing...
        </div>
      )}

      {/* Main Text */}
      <div style={{
        position: 'absolute',
        top: '50%',
        left: '50%',
        transform: 'translate(-50%, -50%)',
        textAlign: 'center',
        pointerEvents: 'none',
        zIndex: 5
      }}>
        <h1 style={{
          margin: 0,
          fontSize: `${config?.fontSize || 64}px`,
          fontWeight: config?.fontWeight || '300',
          color: config?.textColor || '#E8E9ED',
          letterSpacing: '0.15em',
          textTransform: 'uppercase',
          textShadow: `0 0 30px ${config?.accentColor1 || '#00D9FF'}40, 0 0 60px ${config?.accentColor2 || '#6366F1'}20`,
          animation: prefersReducedMotion ? 'none' : 'textGlow 3s ease-in-out infinite'
        }}>
          {config?.text || 'FUTURE'}
        </h1>

        {(config?.showSubtitle !== false) && (
          <p style={{
            margin: '20px 0 0 0',
            fontSize: `${config?.subtitleSize || 13}px`,
            fontWeight: '300',
            color: config?.subtitleColor || '#9CA3AF',
            letterSpacing: '0.2em',
            textTransform: 'uppercase',
            opacity: 0.7
          }}>
            {config?.subtitle || 'NEXT GENERATION INTERFACE'}
          </p>
        )}
      </div>

      {/* Glass Panel */}
      {(config?.showGlassPanel !== false) && (
        <div style={{
          position: 'absolute',
          bottom: '40px',
          left: '50%',
          transform: 'translateX(-50%)',
          padding: '14px 28px',
          background: 'rgba(255, 255, 255, 0.03)',
          backdropFilter: 'blur(20px)',
          WebkitBackdropFilter: 'blur(20px)',
          border: `1px solid ${config?.glassBorderColor || '#FFFFFF'}20`,
          borderRadius: '10px',
          color: config?.textColor || '#E8E9ED',
          fontSize: '11px',
          fontWeight: '300',
          letterSpacing: '0.1em',
          textTransform: 'uppercase',
          boxShadow: '0 8px 32px rgba(0, 0, 0, 0.2)',
          zIndex: 10,
          transition: 'all 250ms ease-out'
        }}>
          <span style={{ opacity: 0.5 }}>Preset:</span>{' '}
          <span style={{ color: config?.accentColor1 || '#00D9FF' }}>
            {presetConfigs[currentPreset]?.name || 'Unknown'}
          </span>
        </div>
      )}

      {/* Preset Selector */}
      {(config?.showPresetSelector !== false) && (
        <div style={{
          position: 'absolute',
          top: '30px',
          right: '30px',
          display: 'flex',
          flexDirection: 'column',
          gap: '8px',
          zIndex: 10
        }}>
          {Object.keys(presetConfigs).map(preset => (
            <button
              key={preset}
              onClick={() => setCurrentPreset(preset)}
              style={{
                padding: '8px 16px',
                backgroundColor: currentPreset === preset 
                  ? 'rgba(255, 255, 255, 0.1)' 
                  : 'rgba(255, 255, 255, 0.03)',
                backdropFilter: 'blur(10px)',
                WebkitBackdropFilter: 'blur(10px)',
                border: `1px solid ${
                  currentPreset === preset 
                    ? config?.accentColor1 || '#00D9FF'
                    : config?.buttonBorderColor || '#3F3F46'
                }`,
                borderRadius: '6px',
                color: config?.buttonTextColor || '#E8E9ED',
                fontSize: '11px',
                fontWeight: '300',
                letterSpacing: '0.08em',
                textTransform: 'uppercase',
                cursor: 'pointer',
                transition: 'all 250ms ease-out',
                outline: 'none',
                textAlign: 'left'
              }}
              onMouseEnter={(e) => {
                e.target.style.backgroundColor = 'rgba(255, 255, 255, 0.08)';
                e.target.style.borderColor = config?.accentColor1 || '#00D9FF';
              }}
              onMouseLeave={(e) => {
                if (currentPreset !== preset) {
                  e.target.style.backgroundColor = 'rgba(255, 255, 255, 0.03)';
                  e.target.style.borderColor = config?.buttonBorderColor || '#3F3F46';
                }
              }}
            >
              {presetConfigs[preset].name}
            </button>
          ))}
        </div>
      )}

      <style>{`
        @keyframes textGlow {
          0%, 100% {
            text-shadow: 0 0 30px ${config?.accentColor1 || '#00D9FF'}40, 0 0 60px ${config?.accentColor2 || '#6366F1'}20;
          }
          50% {
            text-shadow: 0 0 50px ${config?.accentColor1 || '#00D9FF'}60, 0 0 80px ${config?.accentColor2 || '#6366F1'}30, 0 0 100px ${config?.accentColor3 || '#8B5CF6'}15;
          }
        }
      `}</style>
    </div>
  );
}

