        "defaultValue": "0.05",
        "options": ["0.01", "0.03", "0.05", "0.08", "0.1", "0.2"],
        "group": "Tuning"
      },
      "animationDuration": {
        "dataType": "number",
        "displayName": "Duration (ms)",
        "defaultValue": 800,
        "group": "Tuning"
      },
      "fontSize": {
        "dataType": "number",
        "displayName": "Font Size (px)",
        "defaultValue": 64,
        "group": "Typography"
      },
      "fontWeight": {
        "dataType": "select",
        "displayName": "Font Weight",
        "defaultValue": "500",
        "options": ["300", "400", "500", "700", "900"],
        "group": "Typography"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#111827",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#4F46E5",
        "group": "Colors"
      },
      "showReplayButton": {
        "dataType": "booleanValue",
        "displayName": "Show Replay Button",
        "defaultValue": true,
        "group": "Content"
      }
    },
    "layout": {
      "resizeDirection": "horizontal",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  // --- CONFIGURATION ---
  const text = config?.text || "Kinetic Innovation";
  const mode = config?.mode || "entrance";
  const entrancePreset = config?.entrancePreset || "wonderland";
  const hoverPreset = config?.hoverPreset || "weight-shift";
  const loopPreset = config?.loopPreset || "float-wave";
  const intensity = config?.intensity || "medium";
  const staggerAmount = parseFloat(config?.staggerAmount || "0.05");
  const duration = parseInt(config?.animationDuration || "800");
  const fontSize = parseInt(config?.fontSize || "64");
  const fontWeight = config?.fontWeight || "500";
  const textColor = config?.textColor || "#111827";
  const accentColor = config?.accentColor || "#4F46E5";
  const showReplayButton = config?.showReplayButton !== false;

  // --- STATE ---
  const containerRef = React.useRef(null);
  const [activeState, setActiveState] = React.useState(false); // Controls Entrance/Scroll
  const [hoverIdx, setHoverIdx] = React.useState(-1);
  const [key, setKey] = React.useState(0); // For forcing remounts
  const [isReplaying, setIsReplaying] = React.useState(false);

  // --- HELPERS FROM INSPIRATION FILE ---
  const intensityMultiplier = { subtle: 0.5, medium: 1.0, dramatic: 1.5 }[intensity];

  const getRandom = (index, seed, min, max) => {
    const x = Math.sin(index * seed) * 10000;
    const random = x - Math.floor(x);
    return min + random * (max - min);
  };

  const prefersReducedMotion = React.useMemo(() => {
    return typeof window !== 'undefined' 
      ? window.matchMedia('(prefers-reduced-motion: reduce)').matches 
      : false;
  }, []);

  // --- 1. ENTRANCE / SCROLL CONFIG GENERATOR ---
  // Adapted from Component 16's getAnimationConfig
  const getEntranceConfig = (index, total) => {
    const position = index / (total - 1 || 1);
    const middle = total / 2;
    const mult = intensityMultiplier;

    // Default return object
    let res = { 
      opacity: 0, 
      transform: 'none', 
      filter: 'none', 
      transition: `all ${duration}ms cubic-bezier(0.2, 0.8, 0.2, 1)`
    };

    switch (entrancePreset) {
      case 'explosive':
        res.transform = `translate3d(${getRandom(index, 0.5, -150, 150) * mult}px, ${getRandom(index, 0.7, -150, 150) * mult}px, 0) rotate(${getRandom(index, 0.3, -180, 180) * mult}deg) scale(0.3)`;
        res.filter = `blur(${10 * mult}px)`;
        break;
      case 'typewriter':
        res.transform = `translateX(${-20 * mult}px)`;
        res.transition = `opacity 10ms linear`; // Sharp reveal
        break;
      case 'soft-blur':
        res.transform = `scale(${1 + (0.2 * mult)})`;
        res.filter = `blur(${20 * mult}px)`;
        break;
      case 'elastic-up':
        res.transform = `translate3d(0, ${100 * mult}px, 0) scaleY(${1 + (0.5 * mult)})`;
        res.transition = `all ${duration}ms cubic-bezier(0.68, -0.6, 0.32, 1.6)`;
        break;
      case 'elastic-down':
        res.transform = `translate3d(0, ${-100 * mult}px, 0) scaleY(${1 + (0.5 * mult)})`;
        res.transition = `all ${duration}ms cubic-bezier(0.68, -0.6, 0.32, 1.6)`;
        break;
      case '3d-flip-x':
        res.transform = `perspective(1000px) rotateX(${90 * mult}deg)`;
        break;
      case '3d-flip-y':
        res.transform = `perspective(1000px) rotateY(${90 * mult}deg)`;
        break;
      case 'spiral-in':
        res.transform = `rotate(${index * 45 * mult}deg) translateY(${100 * mult}px) scale(0)`;
        break;
      case 'glitch-snap':
        res.transform = `skewX(${60 * mult}deg) translateX(${-50 * mult}px)`;
        res.filter = `blur(${2 * mult}px)`;
        break;
      case 'matrix-decode':
        res.color = '#00FF00'; // Matrix green
        res.filter = `blur(${5 * mult}px)`;
        break;
      case 'domino-fall':
        res.transform = `rotateZ(${-90 * mult}deg)`;
        res.transformOrigin = 'bottom left';
        break;
      case 'converge-center':
        res.transform = `translate3d(${(index - middle) * 100 * mult}px, 0, 0)`;
        break;
      case 'skew-slide':
        res.transform = `skewX(${-45 * mult}deg) translateX(${-100 * mult}px)`;
        break;
      case 'fold-paper':
        res.transform = `perspective(1000px) rotateX(${-90 * mult}deg)`;
        res.transformOrigin = 'top';
        break;
      case 'unfold-paper':
        res.transform = `perspective(1000px) rotateX(${90 * mult}deg)`;
        res.transformOrigin = 'bottom';
        break;
      case 'pixelate':
        res.filter = `blur(${10 * mult}px) contrast(200%)`;
        res.transform = `scale(${1.5 * mult})`;
        break;
      case 'stutter-step':
        res.transform = `translateX(${-50 * mult}px)`;
        res.transition = `all ${duration}ms steps(3)`;
        break;
      case 'wave-enter':
        res.transform = `translateY(${(Math.sin(position * Math.PI * 2) * 50) * mult}px)`;
        break;
      case 'magnetic':
        res.transform = `translate3d(${(position - 0.5) * 150 * mult}px, ${(position - 0.5) * 80 * mult}px, 0) scale(0.2)`;
        res.filter = `blur(${8 * mult}px)`;
        break;
      case 'curtain-reveal':
        res.transform = `rotateY(${-90 * mult}deg)`;
        res.transformOrigin = 'left';
        break;
      case 'wonderland': // From inspiration file
        res.transform = `rotateX(${35 * mult}deg) rotateY(${-40 * mult}deg) rotateZ(${-10 * mult}deg) translate3d(0, ${40 * mult}px, ${-100 * mult}px)`;
        res.filter = `blur(${2 * mult}px)`;
        break;
      default:
        res.transform = `translateY(${20 * mult}px)`;
    }
    return res;
  };

  // --- 2. HOVER STYLE GENERATOR ---
  const getHoverStyle = (isActive) => {
    if (!isActive) return {};
    const t = 'all 0.3s cubic-bezier(0.2, 0.8, 0.2, 1)';
    const mult = intensityMultiplier;

    switch (hoverPreset) {
      case 'weight-shift': return { fontWeight: '900', color: accentColor, transition: t };
      case 'italic-slant': return { fontStyle: 'italic', transform: `skewX(${-15 * mult}deg)`, color: accentColor, transition: t };
      case 'spacing-expand': return { margin: `0 ${10 * mult}px`, color: accentColor, transition: t };
      case 'color-cycle': return { color: accentColor, transition: t };
      case 'underline-grow': return { textDecoration: 'underline', textDecorationColor: accentColor, transition: t };
      case 'strikethrough': return { textDecoration: 'line-through', opacity: 0.6, transition: t };
      case 'scale-up': return { transform: `scale(${1 + (0.5 * mult)})`, color: accentColor, zIndex: 10, transition: t };
      case 'rotate-jiggle': return { transform: `rotate(${getRandom(1, 1, -10, 10) * mult}deg)`, transition: t };
      case 'skew-twist': return { transform: `skewX(${30 * mult}deg)`, color: accentColor, transition: t };
      case 'lift-off': return { transform: `translateY(${-20 * mult}px)`, textShadow: `0 20px 10px rgba(0,0,0,0.1)`, transition: t };
      case 'sink-down': return { transform: `translateY(${10 * mult}px)`, opacity: 0.8, transition: t };
      case 'blur-fade': return { filter: `blur(${5 * mult}px)`, opacity: 0.5, transition: t };
      case 'glow-pulse': return { textShadow: `0 0 10px ${accentColor}, 0 0 20px ${accentColor}`, color: '#fff', transition: t };
      case 'outline-stroke': return { WebkitTextStroke: `1px ${accentColor}`, color: 'transparent', transition: t };
      case 'gradient-wipe': return { backgroundImage: `linear-gradient(to top, ${accentColor}, ${accentColor})`, color: 'transparent', WebkitBackgroundClip: 'text', transition: t };
      case 'rubber-band': return { transform: 'scale(1.25, 0.75)', color: accentColor, transition: t };
      case 'flip-vertical': return { transform: 'rotateX(180deg)', transition: t };
      case 'flip-horizontal': return { transform: 'rotateY(180deg)', transition: t };
      case 'wave-ripple': return { transform: `translateY(${-15 * mult}px)`, transition: t };
      case 'neon-flicker': return { opacity: 0.2, textShadow: 'none', transition: '0.1s' };
      default: return { color: accentColor, transition: t };
    }
  };

  // --- 3. LOOP ANIMATION GENERATOR ---
  const getLoopAnim = (index) => {
    const d = (index * 0.1) + 's';
    const mult = intensityMultiplier;

    // We define animations in CSS (injected below)
    // Here we map preset to animation name + params
    switch (loopPreset) {
      case 'float-wave': return { name: 'float', dur: '3s', delay: d };
      case 'breathe-scale': return { name: 'breathe', dur: '4s', delay: d };
      case 'pulse-opacity': return { name: 'pulse', dur: '1.5s', delay: d };
      case 'bounce-rhythm': return { name: 'bounce', dur: '1s', delay: d };
      case 'spin-slow': return { name: 'spin', dur: '8s', delay: '0s' };
      case 'seesaw-tilt': return { name: 'seesaw', dur: '2s', delay: d };
      case 'wobble-elastic': return { name: 'wobble', dur: '2s', delay: d };
      case 'jelly-morphic': return { name: 'jelly', dur: '2s', delay: d };
      case 'rubber-stretch': return { name: 'rubber', dur: '2s', delay: d };
      case 'heartbeat': return { name: 'heartbeat', dur: '1.5s', delay: '0s' };
      case 'flash-blink': return { name: 'flash', dur: '0.5s', delay: d };
      case 'glitch-twitch': return { name: 'glitch', dur: '0.2s', delay: Math.random() + 's' };
      case 'rainbow-hue': return { name: 'rainbow', dur: '4s', delay: d };
      case 'shimmer-shine': return { name: 'shimmer', dur: '3s', delay: d };
      case 'neon-buzz': return { name: 'neon', dur: '0.1s', delay: '0s' };
      case 'marquee-scroll': return { name: 'marquee', dur: '5s', delay: '0s' };
      case 'orbit-rotate': return { name: 'orbit', dur: '3s', delay: d };
      case 'radar-scan': return { name: 'radar', dur: '2s', delay: d };
      case 'swing-pendulum': return { name: 'swing', dur: '2s', delay: d };
      case 'phase-shift': return { name: 'phase', dur: '2s', delay: d };
      default: return { name: 'float', dur: '3s', delay: d };
    }
  };

  // --- KEYFRAMES ---
  const loopKeyframes = `
    @keyframes float { 0%,100% { transform: translateY(0); } 50% { transform: translateY(${-15 * intensityMultiplier}px); } }
    @keyframes breathe { 0%,100% { transform: scale(1); } 50% { transform: scale(${1 + (0.1 * intensityMultiplier)}); } }
    @keyframes pulse { 0%,100% { opacity: 1; } 50% { opacity: 0.5; } }
    @keyframes bounce { 0%,100% { transform: translateY(0); } 50% { transform: translateY(${-20 * intensityMultiplier}px); } }
    @keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
    @keyframes seesaw { 0%,100% { transform: rotate(${-5 * intensityMultiplier}deg); } 50% { transform: rotate(${5 * intensityMultiplier}deg); } }
    @keyframes wobble { 0%,100% { transform: translateX(0); } 25% { transform: translateX(-5px) rotate(-5deg); } 75% { transform: translateX(5px) rotate(5deg); } }
    @keyframes jelly { 0%,100% { transform: scale(1,1); } 25% { transform: scale(0.9, 1.1); } 75% { transform: scale(1.1, 0.9); } }
    @keyframes rubber { 0% { transform: scale(1); } 30% { transform: scale(1.25, 0.75); } 50% { transform: scale(1.15, 0.85); } 100% { transform: scale(1); } }
    @keyframes heartbeat { 0% { transform: scale(1); } 14% { transform: scale(1.3); } 28% { transform: scale(1); } 42% { transform: scale(1.3); } 70% { transform: scale(1); } }
    @keyframes flash { 0%,100% { opacity: 1; } 50% { opacity: 0; } }
    @keyframes glitch { 0% { transform: translate(0); } 20% { transform: translate(-2px, 2px); } 40% { transform: translate(-2px, -2px); } 60% { transform: translate(2px, 2px); } 80% { transform: translate(2px, -2px); } 100% { transform: translate(0); } }
    @keyframes rainbow { 0% { filter: hue-rotate(0deg); color: ${accentColor}; } 100% { filter: hue-rotate(360deg); color: ${accentColor}; } }
    @keyframes shimmer { 0% { opacity: 1; } 50% { opacity: 0.5; text-shadow: 0 0 10px ${accentColor}; } 100% { opacity: 1; } }
    @keyframes neon { 0%,100% { opacity: 1; text-shadow: 0 0 5px ${accentColor}; } 50% { opacity: 0.8; text-shadow: none; } }
    @keyframes marquee { 0% { transform: translateX(0); } 50% { transform: translateX(10px); } 100% { transform: translateX(0); } }
    @keyframes orbit { 0% { transform: rotate(0deg) translateX(5px) rotate(0deg); } 100% { transform: rotate(360deg) translateX(5px) rotate(-360deg); } }
    @keyframes radar { 0%,100% { opacity: 1; } 50% { opacity: 0.2; } }
    @keyframes swing { 20% { transform: rotate(15deg); } 40% { transform: rotate(-10deg); } 60% { transform: rotate(5deg); } 80% { transform: rotate(-5deg); } 100% { transform: rotate(0deg); } }
    @keyframes phase { 0%,100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.5; transform: scale(0.9); } }
  `;

  // --- REFLOW ENGINE & OBSERVER ---
  React.useEffect(() => {
    setActiveState(false);
    setKey(prev => prev + 1);

    if (mode === 'entrance' || mode === 'manual') {
      requestAnimationFrame(() => requestAnimationFrame(() => setActiveState(true)));
    }
  }, [entrancePreset, loopPreset, hoverPreset, mode, text, intensity]);

  React.useEffect(() => {
    if (mode !== 'scroll' || !containerRef.current) return;

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) setActiveState(true);
        else setActiveState(false); // Snap back when out of view
      });
    }, { threshold: 0.2, rootMargin: "-10% 0px" });

    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [mode, key]);

  const handleReplay = () => {
    setIsReplaying(true);
    setActiveState(false);
    setKey(prev => prev + 1);

    setTimeout(() => {
      requestAnimationFrame(() => setActiveState(true));
      setTimeout(() => setIsReplaying(false), duration + 100);
    }, 50);
  };

  const characters = React.useMemo(() => {
    return text.split('').map((c, i) => ({ char: c === ' ' ? '\u00A0' : c, id: i }));
  }, [text]);

  return (
    <div 
      className="kinetic-v17-wrapper"
      key={key}
      ref={containerRef}
      style={{
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        alignItems: 'center',
        minHeight: '200px',
        padding: '60px 20px',
        width: '100%',
        perspective: '1200px', // Matches inspiration file
        overflow: 'hidden',
        backgroundColor: config?.backgroundColor || 'transparent',
        position: 'relative'
      }}
    >
      <style>{loopKeyframes}</style>

      <div style={{
        fontSize: `${fontSize}px`,
        color: textColor,
        fontWeight: fontWeight,
        lineHeight: 1.1,
        fontFamily: 'Inter, system-ui, sans-serif',
        textAlign: 'center',
        whiteSpace: 'pre-wrap',
        cursor: mode === 'hover' ? 'pointer' : 'default',
        transformStyle: 'preserve-3d'
      }}>
        {characters.map((item, i) => {
          let style = {
            display: 'inline-block',
            backfaceVisibility: 'hidden',
            transition: 'none',
            willChange: 'transform, opacity, filter'
          };

          // Apply Logic
          if (mode === 'entrance' || mode === 'scroll' || mode === 'manual') {
            const startStyle = getEntranceConfig(i, characters.length);
            const endStyle = { opacity: 1, transform: 'translate3d(0,0,0) rotate(0) scale(1)', filter: 'none' };

            // Merge states
            Object.assign(style, activeState ? endStyle : startStyle);

            // Override transition if active
            if (activeState) {
              style.transition = startStyle.transition || `all ${duration}ms cubic-bezier(0.2, 0.8, 0.2, 1)`;
              style.transitionDelay = `${i * staggerAmount}s`;
            }
          } 
          else if (mode === 'hover') {
            const hoverStyle = getHoverStyle(hoverIdx === i);
            Object.assign(style, hoverStyle);
            style.transition = 'all 0.3s cubic-bezier(0.2, 0.8, 0.2, 1)'; // Base transition for hover reset
          } 
          else if (mode === 'loop') {
            const anim = getLoopAnim(i);
            style.animationName = anim.name;
            style.animationDuration = anim.dur;
            style.animationDelay = anim.delay;
            style.animationIterationCount = 'infinite';
            style.animationTimingFunction = 'ease-in-out';
          }

          return (
            <span
              key={item.id}
              style={style}
              onMouseEnter={() => setHoverIdx(i)}
              onMouseLeave={() => setHoverIdx(-1)}
            >
              {item.char}
            </span>
          );
        })}
      </div>

      {(showReplayButton && (mode === 'manual' || mode === 'entrance')) && (
        <button
          onClick={handleReplay}
          disabled={isReplaying}
          style={{
            marginTop: '48px',
            padding: '12px 24px',
            backgroundColor: 'transparent',
            color: textColor,
            border: `1px solid ${textColor}`,
            opacity: isReplaying ? 0.5 : 0.8,
            borderRadius: '6px',
            fontSize: '14px',
            fontWeight: '500',
            cursor: isReplaying ? 'not-allowed' : 'pointer',
            transition: 'all 0.2s ease',
            fontFamily: 'inherit'
          }}
          onMouseEnter={(e) => {
            if (!isReplaying) {
              e.currentTarget.style.opacity = '1';
              e.currentTarget.style.borderColor = accentColor;
              e.currentTarget.style.color = accentColor;
            }
          }}
          onMouseLeave={(e) => {
            if (!isReplaying) {
              e.currentTarget.style.opacity = '0.8';
              e.currentTarget.style.borderColor = textColor;
              e.currentTarget.style.color = textColor;
            }
          }}
        >
          {isReplaying ? 'Animating...' : '↻ Replay Animation'}
        </button>
      )}
    </div>
  );
}

