  const staticTextColor = config?.staticTextColor || '#000000';
  const primaryColor = config?.primaryColor || '#212529';
  const secondaryColor = config?.secondaryColor || '#495057';
  const accentColor = config?.accentColor || '#6C757D';

  const fontSizeFactor = parseInt(config?.fontSize || '6');
  const fontWeight = 'bold';
  const fontFamily = 'Arial, sans-serif';
  const containerHeight = parseInt(config?.containerHeight || '400');
  const lineSpacing = 0.6;

  const [isHovered, setIsHovered] = React.useState(false);

  // --- HELPERS ---

  const getParticleCount = React.useCallback(() => {
    const counts = { low: 500, medium: 1500, high: 3000, ultra: 5000 };
    return counts[particleCount] || 1500;
  }, [particleCount]);

  const getTrailDecay = React.useCallback(() => {
    // Fixed trail length for hover stability, depends slightly on algo
    return 0.92;
  }, []);

  const hexToRgb = React.useCallback((hex) => {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result ? {
      r: parseInt(result[1], 16),
      g: parseInt(result[2], 16),
      b: parseInt(result[3], 16)
    } : { r: 0, g: 0, b: 0 };
  }, []);

  const createNoise = React.useCallback(() => {
    const perm = [];
    for (let i = 0; i < 512; i++) perm[i] = Math.floor(Math.random() * 256);

    const lerp = (t, a, b) => a + t * (b - a);
    const grad = (hash, x, y, z) => {
      const h = hash & 15;
      const u = h < 8 ? x : y;
      const v = h < 4 ? y : h === 12 || h === 14 ? x : z;
      return ((h & 1) === 0 ? u : -u) + ((h & 2) === 0 ? v : -v);
    };

    return (x, y, z) => {
      const X = Math.floor(x) & 255;
      const Y = Math.floor(y) & 255;
      const Z = Math.floor(z) & 255;
      x -= Math.floor(x);
      y -= Math.floor(y);
      z -= Math.floor(z);
      const u = x * x * (3 - 2 * x);
      const v = y * y * (3 - 2 * y);
      const w = z * z * (3 - 2 * z);
      const A = perm[X] + Y, AA = perm[A] + Z, AB = perm[A + 1] + Z;
      const B = perm[X + 1] + Y, BA = perm[B] + Z, BB = perm[B + 1] + Z;
      return lerp(w, lerp(v, lerp(u, grad(perm[AA], x, y, z), grad(perm[BA], x - 1, y, z)),
        lerp(u, grad(perm[AB], x, y - 1, z), grad(perm[BB], x - 1, y - 1, z))),
        lerp(v, lerp(u, grad(perm[AA + 1], x, y, z - 1), grad(perm[BA + 1], x - 1, y, z - 1)),
        lerp(u, grad(perm[AB + 1], x, y - 1, z - 1), grad(perm[BB + 1], x - 1, y - 1, z - 1))));
    };
  }, []);

  // Creates the logic mask (for algorithms to know where text is)
  const createTextMask = React.useCallback((ctx, width, height) => {
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = '#FFFFFF';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const fontSize = Math.min(width / fontSizeFactor, height / 3);
    ctx.font = `${fontWeight} ${fontSize}px ${fontFamily}`;
    ctx.fillText(text1, width / 2, height / 2 - fontSize * lineSpacing);
    ctx.fillText(text2, width / 2, height / 2 + fontSize * lineSpacing);

    const imageData = ctx.getImageData(0, 0, width, height);
    const mask = new Uint8Array(width * height);
    for (let i = 0; i < width * height; i++) {
      mask[i] = imageData.data[i * 4] > 128 ? 1 : 0;
    }
    return mask;
  }, [text1, text2, fontSizeFactor, fontWeight, fontFamily, lineSpacing]);

  // Draws the visible static text when NOT hovering
  const drawStaticText = React.useCallback((ctx, width, height) => {
    // Clear background
    const bgRgb = hexToRgb(backgroundColor);
    ctx.fillStyle = `rgb(${bgRgb.r}, ${bgRgb.g}, ${bgRgb.b})`;
    ctx.fillRect(0, 0, width, height);

    // Draw text
    ctx.fillStyle = staticTextColor;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const fontSize = Math.min(width / fontSizeFactor, height / 3);
    ctx.font = `${fontWeight} ${fontSize}px ${fontFamily}`;

    // Add a slight blur to smooth edges if scale is weird
    ctx.imageSmoothingEnabled = true;

    ctx.fillText(text1, width / 2, height / 2 - fontSize * lineSpacing);
    ctx.fillText(text2, width / 2, height / 2 + fontSize * lineSpacing);
  }, [text1, text2, fontSizeFactor, fontWeight, fontFamily, lineSpacing, backgroundColor, staticTextColor, hexToRgb]);

  const getTextPoints = React.useCallback((mask, width, height, step = 3) => {
    const points = [];
    for (let y = 0; y < height; y += step) {
      for (let x = 0; x < width; x += step) {
        if (mask[y * width + x]) {
          points.push({ x, y });
        }
      }
    }
    return points;
  }, []);

  // --- ALGORITHMS ---
  const algorithms = React.useMemo(() => ({
    physarum: {
      init: (width, height, mask, points) => {
        const agents = [];
        const count = Math.min(getParticleCount(), points.length * 2);
        for (let i = 0; i < count; i++) {
          const pt = points[Math.floor(Math.random() * points.length)];
          agents.push({
            x: pt.x + (Math.random() - 0.5) * 5,
            y: pt.y + (Math.random() - 0.5) * 5,
            angle: Math.random() * Math.PI * 2
          });
        }
        return {
          agents,
          trailMap: new Float32Array(width * height),
          sensorAngle: 45 * Math.PI / 180,
          turnAngle: 45 * Math.PI / 180
        };
      },
      update: (state, width, height, mask, points) => {
        const { agents, trailMap, sensorAngle, turnAngle } = state;
        const sense = (x, y, angle) => {
          const dist = 9;
          const sx = Math.floor(x + Math.cos(angle) * dist);
          const sy = Math.floor(y + Math.sin(angle) * dist);
          if (sx < 0 || sx >= width || sy < 0 || sy >= height) return 0;
          let val = trailMap[sy * width + sx];
          // Gravitate to text
          for (let i = 0; i < points.length; i += 20) {
             const pt = points[i];
             const dx = sx - pt.x, dy = sy - pt.y;
             if (dx*dx + dy*dy < 200) { val += 0.5; break; }
          }
          return val;
        };

        for (let i = 0; i < agents.length; i++) {
          const agent = agents[i];
          const fwd = sense(agent.x, agent.y, agent.angle);
          const left = sense(agent.x, agent.y, agent.angle - sensorAngle);
          const right = sense(agent.x, agent.y, agent.angle + sensorAngle);

          if (fwd < left && fwd < right) {
            agent.angle += (Math.random() - 0.5) * 2 * turnAngle;
          } else if (left < right) {
            agent.angle += turnAngle * speed;
          } else if (right < left) {
            agent.angle -= turnAngle * speed;
          }

          agent.x += Math.cos(agent.angle) * speed;
          agent.y += Math.sin(agent.angle) * speed;

          // Wrap
          if (agent.x < 0) agent.x = width - 1;
          if (agent.x >= width) agent.x = 0;
          if (agent.y < 0) agent.y = height - 1;
          if (agent.y >= height) agent.y = 0;

          const ix = Math.floor(agent.x), iy = Math.floor(agent.y);
          if (ix >= 0 && ix < width && iy >= 0 && iy < height) {
            trailMap[iy * width + ix] = 1;
          }
        }
        const decay = getTrailDecay();
        for (let i = 0; i < trailMap.length; i++) trailMap[i] *= decay;
      },
      render: (ctx, state, width, height, colors) => {
        const { trailMap } = state;
        const imageData = ctx.createImageData(width, height);
        const data = imageData.data;
        const rgb = hexToRgb(colors.primary);
        const bgRgb = hexToRgb(colors.background);

        for (let i = 0; i < trailMap.length; i++) {
          const val = trailMap[i];
          const idx = i * 4;
          data[idx] = bgRgb.r - (bgRgb.r - rgb.r) * val;
          data[idx + 1] = bgRgb.g - (bgRgb.g - rgb.g) * val;
          data[idx + 2] = bgRgb.b - (bgRgb.b - rgb.b) * val;
          data[idx + 3] = 255;
        }
        ctx.putImageData(imageData, 0, 0);
      }
    },
    flowfield: {
      init: (width, height, mask, points) => {
        const particles = [];
        const count = Math.min(getParticleCount(), points.length * 2);
        for (let i = 0; i < count; i++) {
          const pt = points[Math.floor(Math.random() * points.length)];
          particles.push({
            x: pt.x, y: pt.y,
            prevX: pt.x, prevY: pt.y,
            origX: pt.x, origY: pt.y
          });
        }
        return { particles, noise: createNoise(), noiseZ: Math.random() * 1000 };
      },
      update: (state, width, height, mask, points) => {
        const { particles, noise } = state;
        state.noiseZ += 0.002 * speed;
        const noiseScale = 0.003;
        for (let i = 0; i < particles.length; i++) {
          const p = particles[i];
          p.prevX = p.x; p.prevY = p.y;
          const angle = noise(p.x * noiseScale, p.y * noiseScale, state.noiseZ) * Math.PI * 4;
          const newX = p.x + Math.cos(angle) * 1.5 * speed;
          const newY = p.y + Math.sin(angle) * 1.5 * speed;
          const ix = Math.floor(newX), iy = Math.floor(newY);

          if (ix >= 0 && ix < width && iy >= 0 && iy < height && mask[iy * width + ix]) {
            p.x = newX; p.y = newY;
          } else {
            p.x = p.origX; p.y = p.origY;
            p.prevX = p.x; p.prevY = p.y;
          }
        }
      },
      render: (ctx, state, width, height, colors) => {
        const { particles } = state;
        const decay = getTrailDecay();
        const rgb = hexToRgb(colors.background);
        ctx.fillStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${1 - decay})`;
        ctx.fillRect(0, 0, width, height);
        const prgb = hexToRgb(colors.primary);
        ctx.strokeStyle = `rgba(${prgb.r}, ${prgb.g}, ${prgb.b}, 0.3)`;
        ctx.lineWidth = 1;
        ctx.beginPath();
        for (let i = 0; i < particles.length; i++) {
          const p = particles[i];
          ctx.moveTo(p.prevX, p.prevY);
          ctx.lineTo(p.x, p.y);
        }
        ctx.stroke();
      }
    },
    boids: {
      init: (width, height, mask, points) => {
        const boids = [];
        const count = Math.min(getParticleCount() / 2, 800);
        for (let i = 0; i < count; i++) {
          const pt = points[Math.floor(Math.random() * points.length)];
          boids.push({
            x: pt.x, y: pt.y,
            vx: (Math.random() - 0.5) * 4,
            vy: (Math.random() - 0.5) * 4,
            targetX: pt.x, targetY: pt.y
          });
        }
        return { boids };
      },
      update: (state, width, height, mask, points) => {
        const { boids } = state;
        for (let i = 0; i < boids.length; i++) {
          const b = boids[i];
          let sepX = 0, sepY = 0, sepCount = 0;
          let aliX = 0, aliY = 0, aliCount = 0;
          let cohX = 0, cohY = 0, cohCount = 0;
          for (let j = 0; j < boids.length; j++) {
            if (i === j) continue;
            const other = boids[j];
            const dx = b.x - other.x, dy = b.y - other.y;
            const d = Math.sqrt(dx * dx + dy * dy);
            if (d < 15 && d > 0) { sepX += dx / d; sepY += dy / d; sepCount++; }
            if (d < 30) { aliX += other.vx; aliY += other.vy; aliCount++; cohX += other.x; cohY += other.y; cohCount++; }
          }
          if (sepCount > 0) { b.vx += sepX / sepCount * 0.08 * speed; b.vy += sepY / sepCount * 0.08 * speed; }
          if (aliCount > 0) { b.vx += (aliX / aliCount - b.vx) * 0.05 * speed; b.vy += (aliY / aliCount - b.vy) * 0.05 * speed; }
          if (cohCount > 0) { b.vx += (cohX / cohCount - b.x) * 0.002 * speed; b.vy += (cohY / cohCount - b.y) * 0.002 * speed; }
          b.vx += (b.targetX - b.x) * 0.01 * speed;
          b.vy += (b.targetY - b.y) * 0.01 * speed;
          const spd = Math.sqrt(b.vx * b.vx + b.vy * b.vy);
          if (spd > 4) { b.vx = (b.vx / spd) * 4; b.vy = (b.vy / spd) * 4; }
          b.x += b.vx; b.y += b.vy;
        }
      },
      render: (ctx, state, width, height, colors) => {
        const { boids } = state;
        const rgb = hexToRgb(colors.background);
        ctx.fillStyle = `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`;
        ctx.fillRect(0, 0, width, height);
        const prgb = hexToRgb(colors.primary);
        ctx.fillStyle = `rgb(${prgb.r}, ${prgb.g}, ${prgb.b})`;
        for (let i = 0; i < boids.length; i++) {
          const b = boids[i];
          const angle = Math.atan2(b.vy, b.vx);
          ctx.save();
          ctx.translate(b.x, b.y);
          ctx.rotate(angle);
          ctx.beginPath();
          ctx.moveTo(6, 0);
          ctx.lineTo(-3, 2);
          ctx.lineTo(-3, -2);
          ctx.fill();
          ctx.restore();
        }
      }
    },
    reactionDiffusion: {
      init: (width, height, mask) => {
        const w = Math.floor(width / 2);
        const h = Math.floor(height / 2);
        const gridA = new Float32Array(w * h);
        const gridB = new Float32Array(w * h);
        const nextA = new Float32Array(w * h);
        const nextB = new Float32Array(w * h);
        for (let i = 0; i < w * h; i++) {
          gridA[i] = 1;
          const x = i % w, y = Math.floor(i / w);
          const mx = Math.floor(x * 2), my = Math.floor(y * 2);
          if (mx < width && my < height && mask[my * width + mx]) gridB[i] = 1;
          else gridB[i] = 0;
        }
        return { gridA, gridB, nextA, nextB, w, h, dA: 1.0, dB: 0.5, feed: 0.055, kill: 0.062 };
      },
      update: (state) => {
        const { gridA, gridB, nextA, nextB, w, h, dA, dB, feed, kill } = state;
        const laplacian = (grid, x, y) => {
          let sum = grid[y * w + x] * -1;
          sum += (x > 0 ? grid[y * w + x - 1] : grid[y * w + x]) * 0.2;
          sum += (x < w - 1 ? grid[y * w + x + 1] : grid[y * w + x]) * 0.2;
          sum += (y > 0 ? grid[(y - 1) * w + x] : grid[y * w + x]) * 0.2;
          sum += (y < h - 1 ? grid[(y + 1) * w + x] : grid[y * w + x]) * 0.2;
          sum += (x > 0 && y > 0 ? grid[(y - 1) * w + x - 1] : grid[y * w + x]) * 0.05;
          sum += (x < w - 1 && y > 0 ? grid[(y - 1) * w + x + 1] : grid[y * w + x]) * 0.05;
          sum += (x > 0 && y < h - 1 ? grid[(y + 1) * w + x - 1] : grid[y * w + x]) * 0.05;
          sum += (x < w - 1 && y < h - 1 ? grid[(y + 1) * w + x + 1] : grid[y * w + x]) * 0.05;
          return sum;
        };
        for (let iter = 0; iter < Math.ceil(5 * speed); iter++) {
          for (let y = 0; y < h; y++) {
            for (let x = 0; x < w; x++) {
              const idx = y * w + x;
              const a = gridA[idx], b = gridB[idx];
              const laplaceA = laplacian(gridA, x, y);
              const laplaceB = laplacian(gridB, x, y);
              const reaction = a * b * b;
              nextA[idx] = Math.max(0, Math.min(1, a + (dA * laplaceA - reaction + feed * (1 - a))));
              nextB[idx] = Math.max(0, Math.min(1, b + (dB * laplaceB + reaction - (kill + feed) * b)));
            }
          }
          gridA.set(nextA);
          gridB.set(nextB);
        }
      },
      render: (ctx, state, width, height, colors) => {
        const { gridB, w, h } = state;
        const imageData = ctx.createImageData(width, height);
        const data = imageData.data;
        const rgb = hexToRgb(colors.primary);
        const bgRgb = hexToRgb(colors.background);
        for (let y = 0; y < height; y++) {
          for (let x = 0; x < width; x++) {
            const sx = Math.floor(x / 2), sy = Math.floor(y / 2);
            const val = (sx < w && sy < h) ? gridB[sy * w + sx] : 0;
            const idx = (y * width + x) * 4;
            data[idx] = bgRgb.r + (rgb.r - bgRgb.r) * val;
            data[idx + 1] = bgRgb.g + (rgb.g - bgRgb.g) * val;
            data[idx + 2] = bgRgb.b + (rgb.b - bgRgb.b) * val;
            data[idx + 3] = 255;
          }
        }
        ctx.putImageData(imageData, 0, 0);
      }
    },
    gameOfLife: {
      init: (width, height, mask) => {
        const cellSize = 4;
        const cols = Math.floor(width / cellSize);
        const rows = Math.floor(height / cellSize);
        const grid = new Uint8Array(cols * rows);
        const nextGrid = new Uint8Array(cols * rows);
        for (let y = 0; y < rows; y++) {
          for (let x = 0; x < cols; x++) {
            const mx = Math.floor(x * cellSize), my = Math.floor(y * cellSize);
            if (mx < width && my < height && mask[my * width + mx]) grid[y * cols + x] = Math.random() > 0.4 ? 1 : 0;
          }
        }
        return { grid, nextGrid, cols, rows, cellSize, frameCount: 0 };
      },
      update: (state) => {
        const { grid, nextGrid, cols, rows } = state;
        state.frameCount++;
        if (state.frameCount % Math.max(1, Math.floor(3 / speed)) !== 0) return;
        const countNeighbors = (x, y) => {
          let count = 0;
          for (let dy = -1; dy <= 1; dy++) {
            for (let dx = -1; dx <= 1; dx++) {
              if (dx === 0 && dy === 0) continue;
              const nx = (x + dx + cols) % cols;
              const ny = (y + dy + rows) % rows;
              count += grid[ny * cols + nx];
            }
          }
          return count;
        };
        for (let i = 0; i < cols * rows; i++) {
          const x = i % cols, y = Math.floor(i / cols);
          const neighbors = countNeighbors(x, y);
          const alive = grid[i];
          if (alive && (neighbors < 2 || neighbors > 3)) nextGrid[i] = 0;
          else if (!alive && neighbors === 3) nextGrid[i] = 1;
          else nextGrid[i] = alive;
        }
        grid.set(nextGrid);
      },
      render: (ctx, state, width, height, colors) => {
        const { grid, cols, rows, cellSize } = state;
        const rgb = hexToRgb(colors.background);
        ctx.fillStyle = `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`;
        ctx.fillRect(0, 0, width, height);
        const prgb = hexToRgb(colors.primary);
        ctx.fillStyle = `rgb(${prgb.r}, ${prgb.g}, ${prgb.b})`;
        for (let i = 0; i < cols * rows; i++) {
          if (grid[i]) {
            const x = i % cols, y = Math.floor(i / cols);
            ctx.fillRect(x * cellSize, y * cellSize, cellSize - 1, cellSize - 1);
          }
        }
      }
    },
    dla: {
      init: (width, height, mask, points) => {
        const tree = [];
        const treeGrid = new Uint8Array(width * height);
        const walkers = [];
        const count = Math.min(getParticleCount() / 5, 200);
        const seedCount = Math.floor(points.length / 50);
        for (let i = 0; i < seedCount; i++) {
          const pt = points[Math.floor(Math.random() * points.length)];
          tree.push({ x: pt.x, y: pt.y });
          const idx = Math.floor(pt.y) * width + Math.floor(pt.x);
          if (idx >= 0 && idx < treeGrid.length) treeGrid[idx] = 1;
        }
        for (let i = 0; i < count; i++) {
          const pt = points[Math.floor(Math.random() * points.length)];
          walkers.push({ x: pt.x + (Math.random() - 0.5) * 50, y: pt.y + (Math.random() - 0.5) * 50 });
        }
        return { tree, treeGrid, walkers };
      },
      update: (state, width, height, mask, points) => {
        const { tree, treeGrid, walkers } = state;
        const hasNeighbor = (x, y) => {
          const ix = Math.floor(x), iy = Math.floor(y);
          for (let dy = -2; dy <= 2; dy++) {
            for (let dx = -2; dx <= 2; dx++) {
              const nx = ix + dx, ny = iy + dy;
              if (nx >= 0 && nx < width && ny >= 0 && ny < height && treeGrid[ny * width + nx]) return true;
            }
          }
          return false;
        };
        const isNearText = (x, y) => {
           for(let i=0; i<points.length; i+=10) {
             const dx = x - points[i].x, dy = y - points[i].y;
             if (dx*dx+dy*dy < 900) return true;
           }
           return false;
        };
        for (let iter = 0; iter < Math.ceil(30 * speed); iter++) {
          for (let i = 0; i < walkers.length; i++) {
            const w = walkers[i];
            w.x += (Math.random() - 0.5) * 4; w.y += (Math.random() - 0.5) * 4;
            if (!isNearText(w.x, w.y)) {
               const pt = points[Math.floor(Math.random() * points.length)];
               w.x = pt.x + (Math.random()-0.5)*10; w.y = pt.y + (Math.random()-0.5)*10;
               continue;
            }
            if (hasNeighbor(w.x, w.y)) {
              tree.push({ x: w.x, y: w.y });
              const idx = Math.floor(w.y) * width + Math.floor(w.x);
              if (idx >= 0 && idx < treeGrid.length) treeGrid[idx] = 1;
              const pt = points[Math.floor(Math.random() * points.length)];
              w.x = pt.x + (Math.random() - 0.5) * 50;
              w.y = pt.y + (Math.random() - 0.5) * 50;
            }
          }
        }
      },
      render: (ctx, state, width, height, colors) => {
        const { tree } = state;
        const rgb = hexToRgb(colors.background);
        ctx.fillStyle = `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`;
        ctx.fillRect(0,0,width,height);
        const prgb = hexToRgb(colors.primary);
        ctx.fillStyle = `rgb(${prgb.r}, ${prgb.g}, ${prgb.b})`;
        for (let i = 0; i < tree.length; i++) {
          const t = tree[i];
          ctx.beginPath();
          ctx.arc(t.x, t.y, 1.5, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    },
    circlePacking: {
      init: (width, height, mask) => ({ circles: [], growing: [], mask }),
      update: (state, width, height, mask) => {
        const { circles, growing } = state;
        const isInText = (x, y) => {
          const ix = Math.floor(x), iy = Math.floor(y);
          if (ix < 0 || ix >= width || iy < 0 || iy >= height) return false;
          return mask[iy * width + ix] === 1;
        };
        for (let a = 0; a < Math.ceil(5 * speed); a++) {
          for (let attempts = 0; attempts < 20; attempts++) {
            const x = Math.random() * width;
            const y = Math.random() * height;
            if (!isInText(x, y)) continue;
            let valid = true;
            for (let j = 0; j < circles.length; j++) {
              const c = circles[j];
              const dx = x - c.x, dy = y - c.y;
              if (Math.sqrt(dx * dx + dy * dy) < c.r + 2) { valid = false; break; }
            }
            if (valid) {
              const circle = { x, y, r: 1 };
              circles.push(circle);
              growing.push(circle);
              break;
            }
          }
        }
        for (let i = growing.length - 1; i >= 0; i--) {
          const c = growing[i];
          let canGrow = isInText(c.x - c.r - 1, c.y) && isInText(c.x + c.r + 1, c.y) &&
                        isInText(c.x, c.y - c.r - 1) && isInText(c.x, c.y + c.r + 1);
          if (canGrow) {
            for (let j = 0; j < circles.length; j++) {
              if (circles[j] === c) continue;
              const other = circles[j];
              const dx = c.x - other.x, dy = c.y - other.y;
              if (Math.sqrt(dx * dx + dy * dy) < c.r + other.r + 1) { canGrow = false; break; }
            }
          }
          if (canGrow) c.r += 0.5 * speed;
          else growing.splice(i, 1);
        }
      },
      render: (ctx, state, width, height, colors) => {
        const { circles } = state;
        const rgb = hexToRgb(colors.background);
        ctx.fillStyle = `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`;
        ctx.fillRect(0, 0, width, height);
        const prgb = hexToRgb(colors.primary);
        ctx.strokeStyle = `rgb(${prgb.r}, ${prgb.g}, ${prgb.b})`;
        ctx.lineWidth = 1;
        for (let i = 0; i < circles.length; i++) {
          const c = circles[i];
          ctx.beginPath();
          ctx.arc(c.x, c.y, c.r, 0, Math.PI * 2);
          ctx.stroke();
        }
      }
    },
    lorenz: {
      init: (width, height, mask, points) => {
        const attractors = [];
        const count = Math.min(points.length, 100);
        for (let i = 0; i < count; i++) {
          const pt = points[Math.floor(Math.random() * points.length)];
          attractors.push({
            x: 0.1, y: 0.1, z: 0.1,
            centerX: pt.x, centerY: pt.y,
            points: [], scale: 3 + Math.random() * 2
          });
        }
        return { attractors, sigma: 10, rho: 28, beta: 8 / 3, dt: 0.008 };
      },
      update: (state) => {
        const { attractors, sigma, rho, beta, dt } = state;
        for (let iter = 0; iter < Math.ceil(3 * speed); iter++) {
          for (let i = 0; i < attractors.length; i++) {
            const a = attractors[i];
            const dx = sigma * (a.y - a.x) * dt;
            const dy = (a.x * (rho - a.z) - a.y) * dt;
            const dz = (a.x * a.y - beta * a.z) * dt;
            a.x += dx; a.y += dy; a.z += dz;
            const screenX = a.centerX + a.x * a.scale;
            const screenY = a.centerY + (a.z - 25) * a.scale * 0.5;
            a.points.push({ x: screenX, y: screenY });
            if (a.points.length > 50) a.points.shift();
          }
        }
      },
      render: (ctx, state, width, height, colors) => {
        const { attractors } = state;
        const decay = getTrailDecay();
        const rgb = hexToRgb(colors.background);
        ctx.fillStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${1 - decay})`;
        ctx.fillRect(0, 0, width, height);
        const prgb = hexToRgb(colors.primary);
        ctx.strokeStyle = `rgba(${prgb.r}, ${prgb.g}, ${prgb.b}, 0.5)`;
        ctx.lineWidth = 1;
        for (let i = 0; i < attractors.length; i++) {
          const a = attractors[i];
          if (a.points.length > 1) {
            ctx.beginPath();
            ctx.moveTo(a.points[0].x, a.points[0].y);
            for (let j = 1; j < a.points.length; j++) ctx.lineTo(a.points[j].x, a.points[j].y);
            ctx.stroke();
          }
        }
      }
    },
    waveInterference: {
      init: (width, height, mask, points) => {
        const sources = [];
        const step = 20;
        for (let y = 0; y < height; y += step) {
          for (let x = 0; x < width; x += step) {
            if (mask[y * width + x]) {
              sources.push({
                x, y,
                freq: 0.1 + Math.random() * 0.05,
                phase: Math.random() * Math.PI * 2
              });
            }
          }
        }
        return { sources, time: 0 };
      },
      update: (state) => { state.time += 0.2 * speed; },
      render: (ctx, state, width, height, colors) => {
        const { sources, time } = state;
        const imageData = ctx.createImageData(width, height);
        const data = imageData.data;
        const rgb = hexToRgb(colors.primary);
        const bgRgb = hexToRgb(colors.background);
        // Optimization: Low res render or just render points
        // Full pixel render is heavy in JS. Let's do a simplified point render for hover.
        ctx.fillStyle = `rgb(${bgRgb.r}, ${bgRgb.g}, ${bgRgb.b})`;
        ctx.fillRect(0,0,width,height);

        for(let x=0; x<width; x+=2) {
            for(let y=0; y<height; y+=2) {
                let sum = 0;
                // Only calc near center to save perf? No, let's just loop sources
                // Too heavy. Let's switch to rendering circles at source points with pulsing radii.
            }
        }
        // Fallback optimized render:
        ctx.strokeStyle = `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`;
        ctx.lineWidth = 1;
        for(let i=0; i<sources.length; i++) {
            const s = sources[i];
            const r = (Math.sin(time + s.phase) + 1) * 5;
            ctx.beginPath();
            ctx.arc(s.x, s.y, r, 0, Math.PI*2);
            ctx.stroke();
        }
      }
    },
    langtonsAnt: {
        init: (width, height, mask, points) => {
            const cellSize = 2;
            const cols = Math.floor(width/cellSize);
            const rows = Math.floor(height/cellSize);
            const grid = new Uint8Array(cols*rows);
            const ants = [];
            const numAnts = 50;
            const maskGrid = new Uint8Array(cols*rows);
            for(let y=0; y<rows; y++) {
                for(let x=0; x<cols; x++) {
                    if (mask[y*cellSize*width + x*cellSize]) maskGrid[y*cols+x] = 1;
                }
            }
            // Spawn ants on text
            const validPoints = [];
            for(let i=0; i<maskGrid.length; i++) if(maskGrid[i]) validPoints.push(i);

            for(let i=0; i<numAnts; i++){
                const idx = validPoints[Math.floor(Math.random()*validPoints.length)];
                ants.push({ x: idx%cols, y: Math.floor(idx/cols), dir: Math.floor(Math.random()*4) });
            }
            return { grid, ants, cols, rows, cellSize, maskGrid, validPoints };
        },
        update: (state) => {
            const { grid, ants, cols, rows, maskGrid, validPoints } = state;
            const dirs = [[0,-1],[1,0],[0,1],[-1,0]];
            for(let iter=0; iter<50*speed; iter++) {
                for(let i=0; i<ants.length; i++) {
                    const ant = ants[i];
                    const idx = ant.y*cols + ant.x;
                    if(grid[idx] === 0) { ant.dir = (ant.dir+1)%4; grid[idx]=1; }
                    else { ant.dir = (ant.dir+3)%4; grid[idx]=0; }
                    ant.x += dirs[ant.dir][0];
                    ant.y += dirs[ant.dir][1];
                    // Wrap and respawn if off text
                    if(ant.x < 0 || ant.x >= cols || ant.y < 0 || ant.y >= rows || !maskGrid[ant.y*cols+ant.x]) {
                         const nIdx = validPoints[Math.floor(Math.random()*validPoints.length)];
                         ant.x = nIdx%cols; ant.y = Math.floor(nIdx/cols);
                    }
                }
            }
        },
        render: (ctx, state, width, height, colors) => {
            const { grid, cols, rows, cellSize } = state;
            const rgb = hexToRgb(colors.background);
            ctx.fillStyle = `rgb(${rgb.r},${rgb.g},${rgb.b})`;
            ctx.fillRect(0,0,width,height);
            const prgb = hexToRgb(colors.primary);
            ctx.fillStyle = `rgb(${prgb.r},${prgb.g},${prgb.b})`;
            for(let i=0; i<grid.length; i++) {
                if(grid[i]) {
                    const x = i%cols; const y = Math.floor(i/cols);
                    ctx.fillRect(x*cellSize, y*cellSize, cellSize, cellSize);
                }
            }
        }
    },
    brownianTree: {
        init: (width, height, mask, points) => {
            const w = Math.floor(width/2); const h = Math.floor(height/2);
            const grid = new Uint8Array(w*h);
            const walkers = [];
            // Seed grid with text points
            points.forEach(pt => {
                 if(Math.random() < 0.05) {
                     const x = Math.floor(pt.x/2); const y = Math.floor(pt.y/2);
                     if(x>=0 && x<w && y>=0 && y<h) grid[y*w+x] = 1;
                 }
            });
            for(let i=0; i<200; i++) {
                const pt = points[Math.floor(Math.random()*points.length)];
                walkers.push({x: Math.floor(pt.x/2), y: Math.floor(pt.y/2)});
            }
            return { grid, walkers, w, h, points };
        },
        update: (state) => {
            const { grid, walkers, w, h, points } = state;
            const hasNeighbor = (x,y) => {
                if(x>0 && grid[y*w+x-1]) return true;
                if(x<w-1 && grid[y*w+x+1]) return true;
                if(y>0 && grid[(y-1)*w+x]) return true;
                if(y<h-1 && grid[(y+1)*w+x]) return true;
                return false;
            }
            for(let iter=0; iter<50*speed; iter++) {
                walkers.forEach(walker => {
                    walker.x += Math.floor(Math.random()*3)-1;
                    walker.y += Math.floor(Math.random()*3)-1;
                    // Respawn if far
                    if(walker.x<0 || walker.x>=w || walker.y<0 || walker.y>=h) {
                         const pt = points[Math.floor(Math.random()*points.length)];
                         walker.x=Math.floor(pt.x/2); walker.y=Math.floor(pt.y/2);
                    } else if(hasNeighbor(walker.x, walker.y)) {
                        grid[walker.y*w+walker.x] = 1;
                        const pt = points[Math.floor(Math.random()*points.length)];
                        walker.x=Math.floor(pt.x/2); walker.y=Math.floor(pt.y/2);
                    }
                });
            }
        },
        render: (ctx, state, width, height, colors) => {
            const { grid, w, h } = state;
            const rgb = hexToRgb(colors.background);
            ctx.fillStyle = `rgb(${rgb.r},${rgb.g},${rgb.b})`;
            ctx.fillRect(0,0,width,height);
            const prgb = hexToRgb(colors.primary);
            ctx.fillStyle = `rgb(${prgb.r},${prgb.g},${prgb.b})`;
            for(let i=0; i<grid.length; i++) {
                if(grid[i]) {
                    const x = i%w; const y = Math.floor(i/w);
                    ctx.fillRect(x*2, y*2, 2, 2);
                }
            }
        }
    },
    // Placeholders for remaining complex ones mapped to simpler implementations for stability
    lissajous: {
        init: (width, height, mask, points) => {
            const curves = [];
            // Sample fewer points for performance
            for(let i=0; i<points.length; i+=20) {
                const pt = points[i];
                curves.push({
                    cx: pt.x, cy: pt.y,
                    ax: 1+Math.random()*3, ay: 1+Math.random()*3,
                    amp: 5+Math.random()*10,
                    phase: Math.random()*Math.PI*2,
                    path: []
                });
            }
            return { curves, t: 0 };
        },
        update: (state) => {
            state.t += 0.05*speed;
            state.curves.forEach(c => {
                const x = c.cx + Math.sin(c.ax * state.t + c.phase) * c.amp;
                const y = c.cy + Math.cos(c.ay * state.t) * c.amp;
                c.path.push({x,y});
                if(c.path.length > 20) c.path.shift();
            });
        },
        render: (ctx, state, width, height, colors) => {
            const decay = getTrailDecay();
            const rgb = hexToRgb(colors.background);
            ctx.fillStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},${1-decay})`;
            ctx.fillRect(0,0,width,height);
            const prgb = hexToRgb(colors.primary);
            ctx.strokeStyle = `rgba(${prgb.r},${prgb.g},${prgb.b},0.5)`;
            ctx.lineWidth = 1;
            state.curves.forEach(c => {
                if(c.path.length>1) {
                    ctx.beginPath();
                    ctx.moveTo(c.path[0].x, c.path[0].y);
                    for(let i=1; i<c.path.length; i++) ctx.lineTo(c.path[i].x, c.path[i].y);
                    ctx.stroke();
                }
            });
        }
    },
    spirograph: {
        // Reuse lissajous logic but with different math
        init: (w, h, m, p) => {
            const curves = [];
            for(let i=0; i<p.length; i+=25) {
                curves.push({
                    cx: p[i].x, cy: p[i].y,
                    r1: 5+Math.random()*5, r2: 2+Math.random()*3, dist: 5+Math.random()*5,
                    path: []
                });
            }
            return { curves, t: 0 };
        },
        update: (state) => {
            state.t += 0.1*speed;
            state.curves.forEach(c => {
                const t = state.t;
                const x = c.cx + (c.r1-c.r2)*Math.cos(t) + c.dist*Math.cos((c.r1-c.r2)/c.r2*t);
                const y = c.cy + (c.r1-c.r2)*Math.sin(t) - c.dist*Math.sin((c.r1-c.r2)/c.r2*t);
                c.path.push({x,y});
                if(c.path.length>30) c.path.shift();
            });
        },
        render: (ctx, state, width, height, colors) => {
            const rgb = hexToRgb(colors.background);
            ctx.fillStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},0.1)`;
            ctx.fillRect(0,0,width,height);
            const prgb = hexToRgb(colors.primary);
            ctx.strokeStyle = `rgb(${prgb.r},${prgb.g},${prgb.b})`;
            state.curves.forEach(c => {
                if(c.path.length>1) {
                    ctx.beginPath();
                    ctx.moveTo(c.path[0].x, c.path[0].y);
                    for(let i=1; i<c.path.length; i++) ctx.lineTo(c.path[i].x, c.path[i].y);
                    ctx.stroke();
                }
            });
        }
    },
    cellularAutomata: {
        // 1D CA falling down
        init: (w, h, m, p) => {
           const cols = Math.floor(w/2);
           const rows = Math.floor(h/2);
           const cells = new Uint8Array(cols*rows);
           const maskSmall = new Uint8Array(cols*rows);
           for(let y=0; y<rows; y++) {
               for(let x=0; x<cols; x++) {
                   if(m[y*2*w + x*2]) {
                       maskSmall[y*cols+x]=1;
                       if(Math.random()<0.5) cells[y*cols+x]=1;
                   }
               }
           }
           return { cells, maskSmall, cols, rows, rule: 30 };
        },
        update: (state) => {
            const { cells, maskSmall, cols, rows } = state;
            // Shift down
            for(let y=rows-1; y>0; y--) {
                for(let x=0; x<cols; x++) {
                    if(maskSmall[y*cols+x]) cells[y*cols+x] = cells[(y-1)*cols+x];
                }
            }
            // Generate top
            for(let x=0; x<cols; x++) {
                if(maskSmall[x]) {
                    const l = x>0 ? cells[x-1] : 0;
                    const c = cells[x];
                    const r = x<cols-1 ? cells[x+1] : 0;
                    // Simple Rule 30 approx
                    cells[x] = (l ^ (c || r)) ? 1 : 0;
                }
            }
        },
        render: (ctx, state, width, height, colors) => {
            const { cells, cols, rows } = state;
            const rgb = hexToRgb(colors.background);
            ctx.fillStyle = `rgb(${rgb.r},${rgb.g},${rgb.b})`;
            ctx.fillRect(0,0,width,height);
            const prgb = hexToRgb(colors.primary);
            ctx.fillStyle = `rgb(${prgb.r},${prgb.g},${prgb.b})`;
            for(let i=0; i<cells.length; i++) {
                if(cells[i]) {
                    ctx.fillRect((i%cols)*2, Math.floor(i/cols)*2, 2, 2);
                }
            }
        }
    },
    voronoi: {
        init: (w, h, m, p) => {
            const sites = [];
            for(let i=0; i<50; i++) {
                const pt = p[Math.floor(Math.random()*p.length)];
                sites.push({x: pt.x, y: pt.y, vx: (Math.random()-0.5)*2, vy: (Math.random()-0.5)*2});
            }
            return { sites };
        },
        update: (state, w, h, m, p) => {
            state.sites.forEach(s => {
                s.x += s.vx*speed; s.y += s.vy*speed;
                // Bounce within text roughly
                let onText = false;
                for(let i=0; i<p.length; i+=50) {
                     const dx=s.x-p[i].x; const dy=s.y-p[i].y;
                     if(dx*dx+dy*dy < 400) { onText=true; break; }
                }
                if(!onText) {
                    const pt = p[Math.floor(Math.random()*p.length)];
                    s.x = pt.x; s.y = pt.y;
                }
            });
        },
        render: (ctx, state, width, height, colors) => {
            const { sites } = state;
            const rgb = hexToRgb(colors.background);
            ctx.fillStyle = `rgb(${rgb.r},${rgb.g},${rgb.b})`;
            ctx.fillRect(0,0,width,height);
            const prgb = hexToRgb(colors.primary);
            ctx.strokeStyle = `rgb(${prgb.r},${prgb.g},${prgb.b})`;

            // Naive voronoi edges by drawing circles that grow? No, simpler: Delaunay triangulation or just dots
            // Let's just draw the sites and connections
            ctx.beginPath();
            for(let i=0; i<sites.length; i++) {
                for(let j=i+1; j<sites.length; j++) {
                    const dx = sites[i].x - sites[j].x;
                    const dy = sites[i].y - sites[j].y;
                    if(dx*dx + dy*dy < 2500) {
                        ctx.moveTo(sites[i].x, sites[i].y);
                        ctx.lineTo(sites[j].x, sites[j].y);
                    }
                }
            }
            ctx.stroke();
        }
    },
    particleGravity: {
        init: (w, h, m, p) => {
            const particles = [];
            for(let i=0; i<getParticleCount(); i++) {
                const pt = p[Math.floor(Math.random()*p.length)];
                particles.push({x: pt.x, y: pt.y, vx: 0, vy: 0});
            }
            return { particles };
        },
        update: (state, w, h, m, p) => {
            // Particles attracted to mouse? Or just random points on text
            // Let's attract to random text points
            state.particles.forEach(pt => {
                 const target = p[Math.floor(Math.random()*p.length)];
                 const dx = target.x - pt.x;
                 const dy = target.y - pt.y;
                 pt.vx += dx * 0.001 * speed;
                 pt.vy += dy * 0.001 * speed;
                 pt.x += pt.vx;
                 pt.y += pt.vy;
                 pt.vx *= 0.95; pt.vy *= 0.95;
            });
        },
        render: (ctx, state, width, height, colors) => {
            const decay = getTrailDecay();
            const rgb = hexToRgb(colors.background);
            ctx.fillStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},${1-decay})`;
            ctx.fillRect(0,0,width,height);
            const prgb = hexToRgb(colors.primary);
            ctx.fillStyle = `rgb(${prgb.r},${prgb.g},${prgb.b})`;
            state.particles.forEach(p => {
                ctx.fillRect(p.x, p.y, 1, 1);
            });
        }
    }

  }), [getParticleCount, getTrailDecay, hexToRgb, createNoise, speed]);

  // --- RENDERING ---

  const initializeAlgorithm = React.useCallback(() => {
    const canvas = canvasRef.current;
    const textCanvas = textCanvasRef.current;
    const container = containerRef.current;
    if (!canvas || !textCanvas || !container) return;

    const ctx = canvas.getContext('2d');
    const textCtx = textCanvas.getContext('2d');
    const rect = container.getBoundingClientRect();
    const width = Math.floor(rect.width);
    const height = Math.floor(rect.height);

    canvas.width = width;
    canvas.height = height;
    textCanvas.width = width;
    textCanvas.height = height;

    const mask = createTextMask(textCtx, width, height);
    const points = getTextPoints(mask, width, height);

    // Initial Static Draw
    drawStaticText(ctx, width, height);

    const algo = algorithms[algorithm];
    if (algo && algo.init) {
      stateRef.current = {
        ...algo.init(width, height, mask, points),
        mask,
        points,
        width,
        height
      };
    }
  }, [algorithm, algorithms, createTextMask, getTextPoints, drawStaticText]);

  const animate = React.useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const state = stateRef.current;
    if (!state || !state.width) return;

    const { width, height, mask, points } = state;
    const algo = algorithms[algorithm];
    const colors = {
      background: backgroundColor,
      primary: primaryColor,
      secondary: secondaryColor,
      accent: accentColor
    };

    if (algo) {
      if (algo.update) algo.update(state, width, height, mask, points, ctx, colors);
      if (algo.render) algo.render(ctx, state, width, height, colors);
    }

    animationRef.current = requestAnimationFrame(animate);
  }, [algorithm, algorithms, backgroundColor, primaryColor, secondaryColor, accentColor]);

  // Handle Resize
  React.useEffect(() => {
    const handleResize = () => {
       initializeAlgorithm();
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [initializeAlgorithm]);

  // Initial Setup
  React.useEffect(() => {
    initializeAlgorithm();
    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [initializeAlgorithm]);

  // Interaction Handlers
  const handleMouseEnter = () => {
    setIsHovered(true);
    // Initialize specific algo state fresh on hover
    initializeAlgorithm();
    // Start loop
    animationRef.current = requestAnimationFrame(animate);
  };

  const handleMouseLeave = () => {
    setIsHovered(false);
    // Stop loop
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
    // Redraw static text
    const canvas = canvasRef.current;
    if(canvas) drawStaticText(canvas.getContext('2d'), canvas.width, canvas.height);
  };

  return (
    <div
      ref={containerRef}
      className="generative-hover-text"
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      style={{
        position: 'relative',
        width: '100%',
        height: containerHeight + 'px',
        overflow: 'hidden',
        backgroundColor: backgroundColor,
        cursor: 'default',
        userSelect: 'none'
      }}
    >
      {/* Hidden canvas for mask generation */}
      <canvas ref={textCanvasRef} style={{ display: 'none' }} />

      {/* Visible canvas */}
      <canvas
        ref={canvasRef}
        style={{
          display: 'block',
          width: '100%',
          height: '100%',
          imageRendering: ['reactionDiffusion', 'gameOfLife', 'langtonsAnt', 'cellularAutomata'].includes(algorithm) ? 'pixelated' : 'auto'
        }}
      />
    </div>
  );
}

