        "dataType": "number",
        "displayName": "Cursor Radius (px)",
        "defaultValue": 80,
        "group": "Interaction",
        "description": "Area of influence around the mouse"
      },
      "decaySpeed": {
        "dataType": "select",
        "displayName": "Fade Out Speed",
        "defaultValue": "0.02",
        "options": ["0.01", "0.02", "0.05", "0.1", "0.2"],
        "group": "Interaction",
        "description": "How fast the effect disappears after leaving"
      },
      "particleCount": {
        "dataType": "select",
        "displayName": "Particle Density",
        "defaultValue": "high",
        "options": ["low", "medium", "high", "ultra"],
        "group": "Algorithm"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background",
        "defaultValue": "#111111",
        "group": "Colors"
      },
      "staticTextColor": {
        "dataType": "color",
        "displayName": "Static Text Color",
        "defaultValue": "#333333",
        "group": "Colors"
      },
      "activeColor": {
        "dataType": "color",
        "displayName": "Active Effect Color",
        "defaultValue": "#00FF88",
        "group": "Colors"
      },
      "fontSize": {
        "dataType": "number",
        "displayName": "Font Scale",
        "defaultValue": 6,
        "group": "Typography"
      },
      "containerHeight": {
        "dataType": "select",
        "displayName": "Height",
        "defaultValue": "500",
        "options": ["300", "400", "500", "600"],
        "group": "Layout"
      }
    },
    "layout": {
      "resizeDirection": "horizontal",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const canvasRef = React.useRef(null);
  const textCanvasRef = React.useRef(null);
  const containerRef = React.useRef(null);
  const animationRef = React.useRef(null);
  const stateRef = React.useRef({});
  const mouseRef = React.useRef({ x: -1000, y: -1000, active: false });

  // Config
  const text1 = config?.text1 || 'TOUCH';
  const text2 = config?.text2 || 'THE FUTURE';
  const algorithm = config?.algorithm || 'physarum';
  const cursorRadius = parseInt(config?.cursorRadius || '80');
  const decaySpeed = parseFloat(config?.decaySpeed || '0.02');
  const particleCount = config?.particleCount || 'high';

  const backgroundColor = config?.backgroundColor || '#111111';
  const staticTextColor = config?.staticTextColor || '#333333';
  const activeColor = config?.activeColor || '#00FF88';

  const fontSizeFactor = parseInt(config?.fontSize || '6');
  const containerHeight = parseInt(config?.containerHeight || '500');

  // Helpers
  const hexToRgb = React.useCallback((hex) => {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result ? {
      r: parseInt(result[1], 16),
      g: parseInt(result[2], 16),
      b: parseInt(result[3], 16)
    } : { r: 0, g: 255, b: 100 };
  }, []);

  const getParticleCount = React.useCallback(() => {
    const counts = { low: 500, medium: 1500, high: 3000, ultra: 6000 };
    return counts[particleCount] || 3000;
  }, [particleCount]);

  // Create noise function for Flowfield
  const createNoise = React.useCallback(() => {
    const perm = new Uint8Array(512);
    for(let i=0; i<512; i++) perm[i] = Math.floor(Math.random()*256);
    const grad = (hash, x, y, z) => {
      const h = hash & 15, u = h<8?x:y, v = h<4?y:h===12||h===14?x:z;
      return ((h&1)===0?u:-u) + ((h&2)===0?v:-v);
    };
    const lerp = (t, a, b) => a + t * (b - a);
    return (x, y, z) => {
      const X=Math.floor(x)&255, Y=Math.floor(y)&255, Z=Math.floor(z)&255;
      x-=Math.floor(x); y-=Math.floor(y); z-=Math.floor(z);
      const u = x*x*(3-2*x), v = y*y*(3-2*y), w = z*z*(3-2*z);
      const A=perm[X]+Y, AA=perm[A]+Z, AB=perm[A+1]+Z, B=perm[X+1]+Y, BA=perm[B]+Z, BB=perm[B+1]+Z;
      return lerp(w, lerp(v, lerp(u, grad(perm[AA],x,y,z), grad(perm[BA],x-1,y,z)), lerp(u, grad(perm[AB],x,y-1,z), grad(perm[BB],x-1,y-1,z))),
             lerp(v, lerp(u, grad(perm[AA+1],x,y,z-1), grad(perm[BA+1],x-1,y,z-1)), lerp(u, grad(perm[AB+1],x,y-1,z-1), grad(perm[BB+1],x-1,y-1,z-1))));
    };
  }, []);

  const createTextMask = React.useCallback((ctx, width, height) => {
    // Clear and draw text
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = '#FFFFFF';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const fontSize = Math.min(width / fontSizeFactor, height / 2.5);
    ctx.font = `900 ${fontSize}px Inter, sans-serif`;
    ctx.fillText(text1, width / 2, height / 2 - fontSize * 0.55);
    ctx.fillText(text2, width / 2, height / 2 + fontSize * 0.55);

    // Extract points
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const points = [];
    // Optimization: Sample every 4th pixel
    for (let y = 0; y < height; y += 4) {
      for (let x = 0; x < width; x += 4) {
        if (data[(y * width + x) * 4] > 128) {
          points.push({ x, y });
        }
      }
    }
    return { points, imageData };
  }, [text1, text2, fontSizeFactor]);

  // --- ALGORITHMS ---
  const algorithms = React.useMemo(() => ({
    physarum: {
      init: (w, h, points) => {
        const agents = [];
        const count = getParticleCount();
        for (let i = 0; i < count; i++) {
          agents.push({
            x: Math.random() * w, y: Math.random() * h,
            angle: Math.random() * Math.PI * 2,
            life: 0 // Start invisible
          });
        }
        return { agents, trailMap: new Float32Array(w * h) };
      },
      update: (state, w, h, points, mouse) => {
        const { agents, trailMap } = state;
        const sensorDist = 9;
        const turnAngle = 0.5; // Radians

        // Decay trails
        for(let i=0; i<trailMap.length; i++) trailMap[i] *= 0.9;

        // Interaction Radius Squared
        const r2 = cursorRadius * cursorRadius;

        for (let i = 0; i < agents.length; i++) {
          const a = agents[i];

          // Life Logic
          const dx = a.x - mouse.x;
          const dy = a.y - mouse.y;
          const distSq = dx*dx + dy*dy;

          // Wake up if near mouse and on text track
          if (distSq < r2) {
             a.life = Math.min(a.life + 0.1, 1);
             // Gentle Attraction to mouse to keep flow localized
             const angleToMouse = Math.atan2(mouse.y - a.y, mouse.x - a.x);
             a.angle += (angleToMouse - a.angle) * 0.02;
          } else {
             a.life = Math.max(a.life - decaySpeed, 0);
          }

          if (a.life <= 0.01) {
             // Teleport dead agents near mouse for reuse if mouse is active
             if (mouse.active) {
                // Find random text point near mouse
                // Optimization: Just random point in circle
                const angle = Math.random() * Math.PI * 2;
                const r = Math.random() * cursorRadius;
                a.x = mouse.x + Math.cos(angle) * r;
                a.y = mouse.y + Math.sin(angle) * r;
             }
             continue; 
          }

          // Movement Logic (Physarum)
          const ix = Math.floor(a.x);
          const iy = Math.floor(a.y);

          const sense = (ang) => {
             const sx = Math.floor(a.x + Math.cos(ang) * sensorDist);
             const sy = Math.floor(a.y + Math.sin(ang) * sensorDist);
             if (sx<0 || sx>=w || sy<0 || sy>=h) return 0;
             return trailMap[sy*w + sx];
          };

          const f = sense(a.angle);
          const l = sense(a.angle - turnAngle);
          const r = sense(a.angle + turnAngle);

          if (f > l && f > r) { /* Straight */ }
          else if (f < l && f < r) { a.angle += (Math.random()-0.5)*2 * turnAngle; }
          else if (l > r) { a.angle -= turnAngle; }
          else if (r > l) { a.angle += turnAngle; }

          a.x += Math.cos(a.angle);
          a.y += Math.sin(a.angle);

          // Wrap
          if(a.x<0) a.x=w-1; if(a.x>=w) a.x=0;
          if(a.y<0) a.y=h-1; if(a.y>=h) a.y=0;

          // Deposit trail
          const nix = Math.floor(a.x); 
          const niy = Math.floor(a.y);
          if (nix>=0 && nix<w && niy>=0 && niy<h) {
             trailMap[niy*w + nix] += 0.5 * a.life; // Strength depends on life
          }
        }
      },
      render: (ctx, state, w, h, colors) => {
        const { trailMap } = state;
        const id = ctx.createImageData(w, h);
        const d = id.data;
        const rgb = hexToRgb(colors.active);

        for (let i=0; i<trailMap.length; i++) {
           const val = trailMap[i];
           if (val > 0.05) {
             const idx = i*4;
             d[idx] = rgb.r;
             d[idx+1] = rgb.g;
             d[idx+2] = rgb.b;
             d[idx+3] = Math.min(val * 255, 255);
           }
        }
        ctx.putImageData(id, 0, 0);
      }
    },
    flowfield: {
      init: (w, h, points) => {
        const particles = [];
        const count = getParticleCount();
        for(let i=0; i<count; i++) {
           particles.push({ x: Math.random()*w, y: Math.random()*h, life: 0, vx: 0, vy: 0 });
        }
        return { particles, noise: createNoise(), zOff: 0 };
      },
      update: (state, w, h, points, mouse) => {
        state.zOff += 0.01;
        const r2 = cursorRadius * cursorRadius;

        for(let i=0; i<state.particles.length; i++) {
           const p = state.particles[i];
           const dx = p.x - mouse.x;
           const dy = p.y - mouse.y;

           if (dx*dx+dy*dy < r2) {
              p.life = Math.min(p.life + 0.1, 1);
           } else {
              p.life = Math.max(p.life - decaySpeed, 0);
           }

           if (p.life <= 0) {
              if (mouse.active) {
                 // Reset near mouse
                 const ang = Math.random() * 6.28;
                 const rad = Math.random() * cursorRadius;
                 p.x = mouse.x + Math.cos(ang)*rad;
                 p.y = mouse.y + Math.sin(ang)*rad;
              }
              continue;
           }

           const angle = state.noise(p.x * 0.005, p.y * 0.005, state.zOff) * Math.PI * 4;
           p.vx += Math.cos(angle) * 0.2;
           p.vy += Math.sin(angle) * 0.2;
           p.vx *= 0.9; p.vy *= 0.9; // Friction
           p.x += p.vx; p.y += p.vy;
        }
      },
      render: (ctx, state, w, h, colors) => {
         const { particles } = state;
         ctx.clearRect(0,0,w,h);
         ctx.fillStyle = colors.active;
         for(let i=0; i<particles.length; i++) {
            const p = particles[i];
            if (p.life > 0.01) {
               ctx.globalAlpha = p.life;
               ctx.beginPath();
               ctx.arc(p.x, p.y, 1.5, 0, 6.28);
               ctx.fill();
            }
         }
         ctx.globalAlpha = 1;
      }
    },
    reactionDiffusion: {
      init: (w, h, points) => {
         const gridA = new Float32Array(w*h).fill(1);
         const gridB = new Float32Array(w*h).fill(0);
         return { gridA, gridB, nextA: new Float32Array(w*h), nextB: new Float32Array(w*h) };
      },
      update: (state, w, h, points, mouse) => {
         const { gridA, gridB, nextA, nextB } = state;
         const dA=1.0, dB=0.5, feed=0.055, k=0.062;

         // Inject B at mouse
         if (mouse.active) {
            const r = Math.floor(cursorRadius/2);
            for(let y= -r; y<=r; y++) {
               for(let x= -r; x<=r; x++) {
                  if (x*x+y*y < r*r) {
                     const mx = Math.floor(mouse.x + x);
                     const my = Math.floor(mouse.y + y);
                     if (mx>=0 && mx<w && my>=0 && my<h) {
                        gridB[my*w + mx] = 1;
                     }
                  }
               }
            }
         }

         // Simulation Step (Simplified Laplacian)
         // Optimization: Using a fixed kernel for speed in JS
         for(let y=1; y<h-1; y++) {
            for(let x=1; x<w-1; x++) {
               const i = y*w+x;
               const a = gridA[i];
               const b = gridB[i];
               // Simple 5-point laplacian
               const lapA = (gridA[i-1] + gridA[i+1] + gridA[i-w] + gridA[i+w] - 4*a) * 0.2;
               const lapB = (gridB[i-1] + gridB[i+1] + gridB[i-w] + gridB[i+w] - 4*b) * 0.2;

               const reaction = a*b*b;
               nextA[i] = a + (dA*lapA - reaction + feed*(1-a));
               nextB[i] = b + (dB*lapB + reaction - (k+feed)*b);

               // Constrain
               nextA[i] = Math.max(0, Math.min(1, nextA[i]));
               nextB[i] = Math.max(0, Math.min(1, nextB[i]));
            }
         }
         // Swap
         gridA.set(nextA);
         gridB.set(nextB);
      },
      render: (ctx, state, w, h, colors) => {
         const { gridB } = state;
         const id = ctx.createImageData(w, h);
         const d = id.data;
         const rgb = hexToRgb(colors.active);
         for(let i=0; i<gridB.length; i++) {
            const val = gridB[i];
            if (val > 0.1) {
               const idx = i*4;
               d[idx] = rgb.r;
               d[idx+1] = rgb.g;
               d[idx+2] = rgb.b;
               d[idx+3] = val * 255;
            }
         }
         ctx.putImageData(id, 0, 0);
      }
    },
    particleGravity: {
      init: (w, h, points) => {
         const particles = [];
         // Seed from text points
         for(let i=0; i<getParticleCount(); i++) {
            const pt = points[Math.floor(Math.random()*points.length)];
            particles.push({ 
               x: pt.x, y: pt.y, 
               originX: pt.x, originY: pt.y,
               vx: 0, vy: 0, life: 0 
            });
         }
         return { particles };
      },
      update: (state, w, h, points, mouse) => {
         const r2 = cursorRadius * cursorRadius;
         for(let i=0; i<state.particles.length; i++) {
            const p = state.particles[i];
            const dx = p.x - mouse.x;
            const dy = p.y - mouse.y;
            const distSq = dx*dx+dy*dy;

            if (distSq < r2) {
               p.life = Math.min(p.life + 0.1, 1);
               // Repel/Orbit interaction
               const force = (cursorRadius - Math.sqrt(distSq)) / cursorRadius;
               p.vx += dx * force * 0.05;
               p.vy += dy * force * 0.05;
            } else {
               p.life = Math.max(p.life - decaySpeed, 0);
               // Return home
               p.vx += (p.originX - p.x) * 0.05;
               p.vy += (p.originY - p.y) * 0.05;
            }

            p.vx *= 0.9;
            p.vy *= 0.9;
            p.x += p.vx;
            p.y += p.vy;
         }
      },
      render: (ctx, state, w, h, colors) => {
         const { particles } = state;
         ctx.clearRect(0,0,w,h);
         ctx.fillStyle = colors.active;
         for(let i=0; i<particles.length; i++) {
            const p = particles[i];
            if (p.life > 0.01) {
               ctx.globalAlpha = p.life;
               ctx.fillRect(p.x, p.y, 2, 2);
            }
         }
         ctx.globalAlpha = 1;
      }
    },
    // Simple pixel rain that only falls under cursor
    pixelRain: {
       init: (w, h, points) => {
          const drops = [];
          for(let i=0; i<getParticleCount(); i++) {
             drops.push({x: Math.random()*w, y: Math.random()*h, vy: 0, life: 0});
          }
          return { drops };
       },
       update: (state, w, h, points, mouse) => {
          const r2 = cursorRadius * cursorRadius;
          for(let i=0; i<state.drops.length; i++) {
             const d = state.drops[i];
             const dx = d.x - mouse.x;
             const dy = d.y - mouse.y;
             if (dx*dx+dy*dy < r2) {
                d.life = Math.min(d.life+0.1, 1);
                d.vy += 0.5;
             } else {
                d.life = Math.max(d.life - decaySpeed, 0);
                d.vy *= 0.9;
             }
             d.y += d.vy;
             if (d.y > h) {
                d.y = 0; d.vy = 0;
                // Reset to near mouse x
                d.x = mouse.x + (Math.random()-0.5)*cursorRadius*2;
             }
          }
       },
       render: (ctx, state, w, h, colors) => {
          const { drops } = state;
          ctx.clearRect(0,0,w,h);
          ctx.fillStyle = colors.active;
          for(let i=0; i<drops.length; i++) {
             const d = drops[i];
             if(d.life > 0.01) {
                ctx.globalAlpha = d.life;
                ctx.fillRect(d.x, d.y, 1, 6 + d.vy*2);
             }
          }
          ctx.globalAlpha = 1;
       }
    }
  }), [getParticleCount, createNoise, cursorRadius, decaySpeed]);

  // --- LOGIC ---

  const drawStaticText = React.useCallback((ctx, width, height) => {
    const bgRgb = hexToRgb(backgroundColor);
    ctx.fillStyle = `rgb(${bgRgb.r}, ${bgRgb.g}, ${bgRgb.b})`;
    ctx.fillRect(0, 0, width, height);

    ctx.fillStyle = staticTextColor;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const fontSize = Math.min(width / fontSizeFactor, height / 2.5);
    ctx.font = `900 ${fontSize}px Inter, sans-serif`;

    ctx.fillText(text1, width / 2, height / 2 - fontSize * 0.55);
    ctx.fillText(text2, width / 2, height / 2 + fontSize * 0.55);
  }, [text1, text2, fontSizeFactor, backgroundColor, staticTextColor, hexToRgb]);

  const initSimulation = React.useCallback(() => {
    const canvas = canvasRef.current;
    const textCanvas = textCanvasRef.current;
    const container = containerRef.current;
    if (!canvas || !textCanvas || !container) return;

    const rect = container.getBoundingClientRect();
    const width = Math.floor(rect.width);
    const height = Math.floor(rect.height);

    // Resize
    canvas.width = width; canvas.height = height;
    textCanvas.width = width; textCanvas.height = height;

    const tCtx = textCanvas.getContext('2d');
    const { points } = createTextMask(tCtx, width, height);

    // Draw static Layer once
    drawStaticText(tCtx, width, height);

    // Init Algo State
    const algo = algorithms[algorithm];
    // Fallback if not implemented
    const safeAlgo = algo || algorithms.physarum; 

    stateRef.current = {
       ...safeAlgo.init(width, height, points),
       points, width, height
    };

  }, [algorithm, algorithms, createTextMask, drawStaticText]);

  const loop = React.useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const state = stateRef.current;

    if (state.width) {
       const algo = algorithms[algorithm] || algorithms.physarum;

       if (algo.update) {
          algo.update(state, state.width, state.height, state.points, mouseRef.current);
       }
       if (algo.render) {
          algo.render(ctx, state, state.width, state.height, { active: activeColor });
       }
    }

    animationRef.current = requestAnimationFrame(loop);
  }, [algorithm, algorithms, activeColor]);

  // Effects
  React.useEffect(() => {
    initSimulation();
    // Start loop immediately, but it might be idle if mouse far away
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
    animationRef.current = requestAnimationFrame(loop);

    const handleResize = () => initSimulation();
    window.addEventListener('resize', handleResize);
    return () => {
       window.removeEventListener('resize', handleResize);
       cancelAnimationFrame(animationRef.current);
    }
  }, [initSimulation, loop]);

  const handleMouseMove = (e) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    mouseRef.current = {
       x: e.clientX - rect.left,
       y: e.clientY - rect.top,
       active: true
    };
  };

  const handleMouseLeave = () => {
     mouseRef.current.active = false;
     // We don't stop the loop because we need the decay animation to finish
     // We just move the mouse target far away so logic knows to decay
     mouseRef.current.x = -1000;
     mouseRef.current.y = -1000;
  };

  return (
    <div
      ref={containerRef}
      className="interactive-spotlight"
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{
        position: 'relative',
        width: '100%',
        height: containerHeight + 'px',
        backgroundColor: backgroundColor,
        cursor: 'none', // Hide default cursor for immersion
        overflow: 'hidden',
        userSelect: 'none'
      }}
    >
      {/* Static Text Layer (Bottom) */}
      <canvas 
        ref={textCanvasRef} 
        style={{ 
           position: 'absolute', top: 0, left: 0, width: '100%', height: '100%',
           pointerEvents: 'none'
        }} 
      />

      {/* Dynamic Effect Layer (Top) */}
      <canvas 
        ref={canvasRef} 
        style={{ 
           position: 'absolute', top: 0, left: 0, width: '100%', height: '100%',
           mixBlendMode: 'screen' // Blend nicely with background
        }} 
      />

      {/* Custom Cursor Hint */}
      <div style={{
         position: 'absolute', bottom: 20, right: 20, 
         color: staticTextColor, fontSize: '10px', 
         fontFamily: 'sans-serif', opacity: 0.5, pointerEvents: 'none'
      }}>
         MOVE CURSOR TO REVEAL
      </div>
    </div>
  );
}

