        "defaultValue": "DISSOLVE",
        "group": "Content"
      },
      "effectType": {
        "dataType": "select",
        "displayName": "Interaction Physics",
        "defaultValue": "repel",
        "options": ["repel", "liquid", "magnetic", "pixelate", "wobble"],
        "group": "Physics",
        "description": "How the particles react to the cursor"
      },
      "particleDensity": {
        "dataType": "select",
        "displayName": "Resolution (Density)",
        "defaultValue": "medium",
        "options": ["low", "medium", "high", "ultra"],
        "group": "Physics",
        "description": "Ultra looks solid but needs a powerful GPU"
      },
      "cursorRadius": {
        "dataType": "number",
        "displayName": "Influence Radius",
        "defaultValue": 80,
        "group": "Physics"
      },
      "returnSpeed": {
        "dataType": "select",
        "displayName": "Healing Speed",
        "defaultValue": "0.1",
        "options": ["0.05", "0.1", "0.2", "0.3"],
        "group": "Physics",
        "description": "How fast text reforms after disturbance"
      },
      "particleSize": {
        "dataType": "number",
        "displayName": "Particle Size",
        "defaultValue": 2,
