function Component({ config = {} }) {
  const canvasRef = React.useRef(null);
  const containerRef = React.useRef(null);
  const requestRef = React.useRef(null);
  const particlesRef = React.useRef([]);
  const mouseRef = React.useRef({ x: -9999, y: -9999 });

  // Config Parsing
  const text = config?.text || "DISSOLVE";
  const effectType = config?.effectType || "repel";
  const particleDensity = config?.particleDensity || "medium";
  const cursorRadius = parseInt(config?.cursorRadius || "80");
  const returnSpeed = parseFloat(config?.returnSpeed || "0.1");
  const particleSize = parseFloat(config?.particleSize || "2");
  const fontSize = parseInt(config?.fontSize || "120");
  const fontWeight = config?.fontWeight || "900";
  const fontFamily = config?.fontFamily || "Inter, sans-serif";
  const color = config?.color || "#ffffff";
  const backgroundColor = config?.backgroundColor || "#111111";

  // Density Mapping (Gap between scan lines)
  const gapMap = { low: 5, medium: 4, high: 3, ultra: 2 };
  const gap = gapMap[particleDensity] || 4;

  // --- INITIALIZATION ---
  const initParticles = React.useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    const width = canvas.width;
    const height = canvas.height;

    // 1. Clear & Draw text to offscreen buffer
    ctx.fillStyle = backgroundColor;
    ctx.fillRect(0, 0, width, height);

    ctx.fillStyle = "#FFFFFF"; // Scan in white
    ctx.font = `${fontWeight} ${fontSize}px ${fontFamily}`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(text, width / 2, height / 2);

    // 2. Scan pixel data
    const imageData = ctx.getImageData(0, 0, width, height).data;
    const particles = [];

    // 3. Create particles from pixels
    for (let y = 0; y < height; y += gap) {
      for (let x = 0; x < width; x += gap) {
        const index = (y * width + x) * 4;
        const alpha = imageData[index + 3]; // Check alpha channel/brightness

        if (alpha > 128) {
          particles.push({
            x: x,           // Current X
            y: y,           // Current Y
            originX: x,     // Home X
            originY: y,     // Home Y
            vx: 0,          // Velocity X
            vy: 0,          // Velocity Y
            size: particleSize,
            color: color
          });
        }
      }
    }

    particlesRef.current = particles;
  }, [text, fontSize, fontWeight, fontFamily, gap, color, particleSize, backgroundColor]);

  // --- PHYSICS ENGINE ---
  const update = React.useCallback(() => {
    const particles = particlesRef.current;
    const mouse = mouseRef.current;
    const radiusSq = cursorRadius * cursorRadius;

    // Noise function for Liquid effect
    const time = Date.now() * 0.002;

    for (let i = 0; i < particles.length; i++) {
      const p = particles[i];

      // distance to mouse
      const dx = mouse.x - p.x;
      const dy = mouse.y - p.y;
      const distSq = dx * dx + dy * dy;

      let forceX = 0;
      let forceY = 0;

      // --- INTERACTION PHASE ---
      if (distSq < radiusSq) {
        const dist = Math.sqrt(distSq);
        const force = (cursorRadius - dist) / cursorRadius; // 0 to 1 strength based on proximity

        if (effectType === 'repel') {
          const angle = Math.atan2(dy, dx);
          forceX = -Math.cos(angle) * force * 5;
          forceY = -Math.sin(angle) * force * 5;
        } 
        else if (effectType === 'liquid') {
          // Perlin-ish noise approximation
          const noise = Math.sin(p.originY * 0.1 + time) * Math.cos(p.originX * 0.1 + time);
          forceX = noise * force * 2;
          forceY = -force * 2; // Float up
        }
        else if (effectType === 'magnetic') {
          // Orbit/Attract
          const angle = Math.atan2(dy, dx);
          forceX = Math.cos(angle + 1.5) * force * 5; // Tangential force
          forceY = Math.sin(angle + 1.5) * force * 5;
        }
        else if (effectType === 'wobble') {
           forceX = (Math.random() - 0.5) * force * 10;
           forceY = (Math.random() - 0.5) * force * 10;
        }
        else if (effectType === 'pixelate') {
           // Snap to larger grid
           const snap = 20;
           const targetX = Math.floor(p.originX / snap) * snap;
           const targetY = Math.floor(p.originY / snap) * snap;
           p.x += (targetX - p.x) * 0.2;
           p.y += (targetY - p.y) * 0.2;
           continue; // Skip normal physics for this one
        }
      }

      // --- PHYSICS INTEGRATION ---

      // Apply Interaction Force
      p.vx += forceX;
      p.vy += forceY;

      // Homing Force (Spring Physics)
      // Pull particle back to originX/originY
      const homeDx = p.originX - p.x;
      const homeDy = p.originY - p.y;

      p.vx += homeDx * returnSpeed; // Spring stiffness
      p.vy += homeDy * returnSpeed;

      // Friction / Damping (Prevents eternal oscillation)
      p.vx *= 0.85; 
      p.vy *= 0.85;

      // Move
      p.x += p.vx;
      p.y += p.vy;
    }
  }, [effectType, cursorRadius, returnSpeed]);

  // --- RENDER LOOP ---
  const render = React.useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    // Clear Screen
    ctx.fillStyle = backgroundColor;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    update();

    // Draw Particles
    const particles = particlesRef.current;
    ctx.fillStyle = color;

    for (let i = 0; i < particles.length; i++) {
      const p = particles[i];
      // Rects are faster than Arcs at high count
      ctx.fillRect(p.x, p.y, p.size, p.size); 
    }

    requestRef.current = requestAnimationFrame(render);
  }, [update, color, backgroundColor]);

  // --- SETUP ---
  React.useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;

    const handleResize = () => {
      if (container && canvas) {
        canvas.width = container.offsetWidth;
        canvas.height = container.offsetHeight;
        initParticles();
      }
    };

    window.addEventListener('resize', handleResize);
    handleResize(); // Initial sizing

    requestRef.current = requestAnimationFrame(render);

    return () => {
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(requestRef.current);
    };
  }, [initParticles, render]);

  // --- INTERACTION ---
  const handleMouseMove = (e) => {
    if (!canvasRef.current) return;
    const rect = canvasRef.current.getBoundingClientRect();
    mouseRef.current = {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top
    };
  };

  const handleMouseLeave = () => {
    // Move mouse far away so text heals
    mouseRef.current = { x: -9999, y: -9999 };
  };

  return (
    <div 
      ref={containerRef}
      className="particle-morph-container"
      style={{
        width: '100%',
        height: '400px', // Default height
        backgroundColor: backgroundColor,
        cursor: 'none', // Hide standard cursor for immersion
        overflow: 'hidden',
        position: 'relative'
      }}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
    >
      <canvas
        ref={canvasRef}
        style={{ display: 'block' }}
      />
      {/* Optional: Custom Cursor Hint */}
      <div style={{
        position: 'absolute',
        bottom: 20,
        right: 20,
        color: color,
        opacity: 0.3,
        fontSize: '12px',
        fontFamily: fontFamily,
        pointerEvents: 'none'
      }}>
        TOUCH THE TEXT
      </div>
    </div>
  );
}

