// Individual animated text row
function AnimatedTextRow({ text, preset, fontSize, fontWeight, letterSpacing, textColor, hoverColor, hoverRadius, intensity, showLabel }) {
  const [mousePosition, setMousePosition] = React.useState({ x: 0, y: 0 });
  const [isHovering, setIsHovering] = React.useState(false);
  const [charPositions, setCharPositions] = React.useState([]);
  const containerRef = React.useRef(null);
  const charRefs = React.useRef([]);
  const animationRef = React.useRef(null);
  const smoothMouseRef = React.useRef({ x: 0, y: 0 });

  const characters = React.useMemo(() => {
    return text.split('').map((char, index) => ({
      char: char === ' ' ? '\u00A0' : char,
      index,
      isSpace: char === ' '
    }));
  }, [text]);

  const intensityMultiplier = React.useMemo(() => ({
    subtle: 0.5,
    medium: 1.0,
    dramatic: 1.5
  })[intensity] || 1.0, [intensity]);

  const accentColor = '#71717A';
  const glowColor = '#A1A1AA';

  // Update character positions
  React.useEffect(() => {
    const updatePositions = () => {
      const positions = charRefs.current.map(ref => {
        if (!ref) return { x: 0, y: 0, width: 0, height: 0 };
        const rect = ref.getBoundingClientRect();
        const containerRect = containerRef.current?.getBoundingClientRect() || { left: 0, top: 0 };
        return {
          x: rect.left - containerRect.left + rect.width / 2,
          y: rect.top - containerRect.top + rect.height / 2,
          width: rect.width,
          height: rect.height
        };
      });
      setCharPositions(positions);
    };

    updatePositions();
    window.addEventListener('resize', updatePositions);
    return () => window.removeEventListener('resize', updatePositions);
  }, [text, fontSize]);

  // Smooth mouse tracking
  React.useEffect(() => {
    const animate = () => {
      smoothMouseRef.current.x += (mousePosition.x - smoothMouseRef.current.x) * 0.15;
      smoothMouseRef.current.y += (mousePosition.y - smoothMouseRef.current.y) * 0.15;
      animationRef.current = requestAnimationFrame(animate);
    };
    animationRef.current = requestAnimationFrame(animate);
    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
