        const blink = Math.sin(t * 8) > 0;
        opacity = isCursor && blink ? 0.3 : 1;
        transform = isCursor ? 'scaleY(1.2)' : 'none';
        if (isCursor) {
          textShadow = `2px 0 0 ${accentColor}`;
        }
        break;
      }

      case 'bounce-sequence': {
        const bouncePhase = (t * 3 + index * 0.5) % (Math.PI * 2);
        const bounceY = -Math.abs(Math.sin(bouncePhase)) * 35 * m;
        const squash = Math.cos(bouncePhase) > 0.9 ? 1.2 : 1;
        transform = `translateY(${bounceY}px) scaleX(${squash}) scaleY(${2 - squash})`;
        break;
      }

      case 'rotation-carousel': {
        const angle = t * 60 + index * (360 / characters.length);
        const z = Math.sin(angle * Math.PI / 180) * 50 * m;
        const scale = 0.8 + (Math.cos(angle * Math.PI / 180) + 1) * 0.2;
        transform = `perspective(500px) translateZ(${z}px) scale(${scale})`;
        opacity = 0.5 + (Math.cos(angle * Math.PI / 180) + 1) * 0.25;
        break;
      }

      case 'scale-breathe': {
        const breathe = Math.sin(t * 1.2 + index * 0.2);
        const scale = 1 + breathe * 0.25 * m;
        const y = breathe * 8 * m;
        transform = `translateY(${y}px) scale(${scale})`;
        opacity = 0.6 + breathe * 0.2 + 0.2;
        break;
      }

      case 'glitch-static': {
        const glitchChance = getRandom(Math.floor(t * 8), index + 1);
        if (glitchChance > 0.85) {
          const offsetX = (getRandom(Math.floor(t * 12), index * 2) - 0.5) * 15 * m;
          const offsetY = (getRandom(Math.floor(t * 15), index * 3) - 0.5) * 8 * m;
          const skewVal = (getRandom(Math.floor(t * 10), index * 4) - 0.5) * 20 * m;
          transform = `translate(${offsetX}px, ${offsetY}px) skewX(${skewVal}deg)`;
          textShadow = `${offsetX}px 0 ${accentColor}, ${-offsetX}px 0 ${secondaryColor}`;
          opacity = getRandom(Math.floor(t * 20), index) > 0.3 ? 1 : 0.5;
        } else {
          transform = 'none';
        }
        break;
      }

      case 'aurora-shimmer': {
        const hue = (t * 30 + index * 20) % 360;
        const shimmer = Math.sin(t * 2 + index * 0.5);
        const y = shimmer * 15 * m;
        const blur = (shimmer + 1) * 3 * m;
        transform = `translateY(${y}px)`;
        color = `hsl(${hue}, 70%, 70%)`;
        textShadow = `0 0 ${blur}px hsl(${hue}, 80%, 60%), 0 0 ${blur * 2}px hsl(${(hue + 60) % 360}, 70%, 50%)`;
        break;
      }

      case 'magnetic-field': {
        const fieldX = Math.sin(t * 1.5 + index * 0.7) * Math.cos(t * 0.8) * 20 * m;
        const fieldY = Math.cos(t * 1.2 + index * 0.5) * Math.sin(t * 0.9) * 25 * m;
        const rotate = Math.sin(t * 0.7 + index * 0.4) * 12 * m;
        transform = `translate(${fieldX}px, ${fieldY}px) rotate(${rotate}deg)`;
        break;
      }

      case 'liquid-flow': {
        const flowX = Math.sin(t * 0.9 + index * 0.6) * 18 * m;
        const flowY = Math.cos(t * 0.7 + index * 0.4) * 22 * m;
        const scaleX = 1 + Math.sin(t * 1.1 + index * 0.3) * 0.15 * m;
        const scaleY = 1 + Math.cos(t * 0.9 + index * 0.5) * 0.1 * m;
        const skew = Math.sin(t * 0.6 + index * 0.4) * 8 * m;
        transform = `translate(${flowX}px, ${flowY}px) scale(${scaleX}, ${scaleY}) skewX(${skew}deg)`;
        break;
      }

      case 'quantum-vibration': {
        const vibX = (getRandom(Math.floor(t * 30), index + t) - 0.5) * 4 * m;
        const vibY = (getRandom(Math.floor(t * 35), index * 2 + t) - 0.5) * 4 * m;
        const baseX = Math.sin(t * 2 + index * 0.8) * 8 * m;
        const baseY = Math.cos(t * 1.5 + index * 0.6) * 10 * m;
        transform = `translate(${baseX + vibX}px, ${baseY + vibY}px)`;
        opacity = 0.7 + getRandom(Math.floor(t * 25), index) * 0.3;
        break;
      }

      default: {
        const y = Math.sin(t * 2 + phase) * 15 * m;
        transform = `translateY(${y}px)`;
      }
    }

    return {
      display: 'inline-block',
      color,
      transform,
      filter,
      textShadow,
      opacity,
      transformStyle: 'preserve-3d',
      willChange: 'transform, opacity, filter, text-shadow'
    };
  }, [
    time, staggerOffset, intensityMultiplier, characters.length, preset,
    prefersReducedMotion, textColor, accentColor, glowColor, secondaryColor, getRandom
  ]);

  // Unique ID
  const uniqueId = React.useMemo(() => {
    return `loop-${Math.random().toString(36).substr(2, 9)}`;
  }, []);

  const handleMouseEnter = React.useCallback(() => setIsHovering(true), []);
  const handleMouseLeave = React.useCallback(() => setIsHovering(false), []);
  const togglePause = React.useCallback(() => setIsPaused(p => !p), []);

  return (
    <div
      className="text-loop-container"
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      style={{
        position: 'relative',
        width: '100%',
        minHeight: minHeight === 'auto' ? 'auto' : `${minHeight}px`,
        backgroundColor: backgroundColor,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        padding: `${containerPadding}px`,
        boxSizing: 'border-box',
        overflow: 'hidden'
      }}
    >
      <div
        style={{
          fontSize: `clamp(24px, ${fontSize}px, 10vw)`,
          fontWeight: fontWeight,
          letterSpacing: letterSpacing,
          textAlign: textAlign,
          textTransform: textTransform,
          color: textColor,
          lineHeight: 1.3,
          perspective: '1200px',
          transformStyle: 'preserve-3d',
          maxWidth: '100%',
          wordBreak: 'break-word'
        }}
        aria-label={text}
      >
        {characters.map((char, index) => (
          <span
            key={`${uniqueId}-${index}`}
            style={getCharacterStyles(char, index)}
            aria-hidden="true"
          >
            {char.char}
          </span>
        ))}
      </div>

      {showControls && (
        <button
          onClick={togglePause}
          onMouseEnter={() => setButtonHovered(true)}
          onMouseLeave={() => setButtonHovered(false)}
          aria-label={isPaused ? 'Play animation' : 'Pause animation'}
          style={{
            marginTop: '40px',
            padding: '12px 28px',
            fontSize: '13px',
            fontWeight: '400',
            letterSpacing: '0.1em',
            textTransform: 'uppercase',
            color: buttonHovered ? backgroundColor : accentColor,
            backgroundColor: buttonHovered ? accentColor : 'transparent',
            border: `1px solid ${secondaryColor}`,
            borderRadius: '0',
            cursor: 'pointer',
            transition: 'all 300ms ease-out',
            outline: 'none',
            display: 'flex',
            alignItems: 'center',
            gap: '10px'
          }}
        >
          <span style={{
            width: '8px',
            height: '8px',
            borderRadius: '50%',
            backgroundColor: isPaused ? accentColor : 'transparent',
            border: `1px solid ${buttonHovered ? backgroundColor : accentColor}`,
            transition: 'all 300ms ease-out'
          }} />
          {isPaused ? 'Play' : 'Pause'}
        </button>
      )}

      {pauseOnHover && (
        <div
          style={{
            marginTop: '20px',
            fontSize: '11px',
            fontWeight: '400',
            letterSpacing: '0.15em',
            textTransform: 'uppercase',
            color: secondaryColor,
            opacity: 0.5
          }}
        >
          Hover to pause
        </div>
      )}
    </div>
  );
}

