      transform: isVisible(4) ? 'translateY(0)' : 'translateY(30px)',
      transition: `all 0.6s cubic-bezier(0.22, 1, 0.36, 1) ${index * 0.08}s`
    }),
    productNumber: {
      fontSize: '12px',
      fontWeight: '400',
      color: secondaryTextColor,
      marginLeft: '16px'
    },
    productName: {
      fontSize: '18px',
      fontWeight: '400',
      flex: 1
    },
    productIcon: {
      color: secondaryTextColor,
      opacity: 0.5
    },
    clientsSection: {
      padding: '120px 48px',
      borderTop: `1px solid ${borderColor}`
    },
    clientsContent: {
      maxWidth: '1400px',
      margin: '0 auto'
    },
    clientsLabel: {
      fontSize: '13px',
      fontWeight: '400',
      letterSpacing: '0.2em',
      color: secondaryTextColor,
      marginBottom: '48px',
      textTransform: 'uppercase'
    },
    clientsMarquee: {
      display: 'flex',
      gap: '32px',
      flexWrap: 'wrap'
    },
    clientTag: (index) => ({
      padding: '16px 32px',
      border: `1px solid ${borderColor}`,
      borderRadius: '100px',
      fontSize: '15px',
      fontWeight: '400',
      opacity: isVisible(5) ? 1 : 0,
      transform: isVisible(5) ? 'translateY(0) scale(1)' : 'translateY(20px) scale(0.9)',
      transition: `all 0.5s cubic-bezier(0.22, 1, 0.36, 1) ${index * 0.05}s`
    }),
    ctaSection: {
      padding: '200px 48px',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      textAlign: 'center'
    },
    ctaTitleStyle: {
      fontSize: 'clamp(48px, 10vw, 140px)',
      fontWeight: '300',
      lineHeight: '1',
      marginBottom: '64px',
      letterSpacing: '-0.03em',
      opacity: isVisible(6) ? 1 : 0,
      transform: isVisible(6) ? 'translateY(0) scale(1)' : 'translateY(60px) scale(0.95)',
      transition: 'all 1s cubic-bezier(0.22, 1, 0.36, 1)'
    },
    ctaButtonStyle: {
      display: 'inline-flex',
      alignItems: 'center',
      gap: '16px',
      padding: '24px 56px',
      backgroundColor: 'transparent',
      color: primaryTextColor,
      border: `1px solid ${borderColor}`,
      borderRadius: '100px',
      fontSize: '16px',
      fontWeight: '400',
      cursor: 'pointer',
      transition: 'all 0.4s ease',
      opacity: isVisible(6) ? 1 : 0,
      transform: isVisible(6) ? 'translateY(0)' : 'translateY(30px)',
      transitionDelay: '0.2s'
    },
    footer: {
      padding: '48px',
      borderTop: `1px solid ${borderColor}`,
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      color: secondaryTextColor,
      fontSize: '14px'
    },
    keyframes: `
      @keyframes scrollDown {
        0% { transform: translateY(0); opacity: 1; }
        50% { opacity: 1; }
        100% { transform: translateY(40px); opacity: 0; }
      }
    `
  };

  return (
    <div style={styles.page} className="about-kinetic">
      <link href="https://fonts.googleapis.com/css2?family=Noto+Sans+Hebrew:wght@300;400;500&display=swap" rel="stylesheet" />
      <style>{styles.keyframes}</style>

      {/* Fixed Header */}
      <header style={styles.header}>
        <div style={styles.logo}>{companyName}</div>
      </header>

      {/* Hero Section */}
      <section style={styles.hero} ref={setSectionRef(0)}>
        <div style={styles.heroWords}>
          <span style={styles.heroWord(0)}>{heroWord1}</span>
          <span style={{...styles.heroWord(1), ...styles.heroWordOutline}}>{heroWord2}</span>
          <span style={styles.heroWord(2)}>{heroWord3}</span>
        </div>
        <div style={styles.scrollIndicator}>
          <div style={styles.scrollLine}>
            <div style={styles.scrollDot}></div>
          </div>
        </div>
      </section>

      {/* Intro Section */}
      <section style={styles.introSection} ref={setSectionRef(1)}>
        <div style={styles.introContent}>
          <div style={styles.introLabel}>מי אנחנו</div>
          <p style={styles.introText}>{introText}</p>
        </div>
      </section>

      {/* Stats Section */}
      <section style={styles.statsSection} ref={setSectionRef(2)}>
        <div style={styles.statsGrid}>
          {stats.map((stat, index) => (
            <div key={index} style={styles.statItem(index)}>
              <div style={styles.statValue}>{stat.value}</div>
              <div style={styles.statLabel}>{stat.label}</div>
            </div>
          ))}
        </div>
      </section>

      {/* Story Section - Split */}
      <section style={styles.storySection} ref={setSectionRef(3)}>
        <div style={styles.storyLeft}>
          <div style={styles.storyLabel}>הסיפור שלנו</div>
          <h2 style={styles.storyTitle}>מובילים את השוק מאז 2008</h2>
          <p style={styles.storyParagraph}>{storyText}</p>
        </div>
        <div style={styles.storyRight}>
          <div style={styles.storyLabel}>השירות</div>
          <h2 style={styles.storyTitle}>ליווי מקצועי מלא</h2>
          <p style={styles.storyParagraph}>{servicesText}</p>
        </div>
      </section>

      {/* Products Section */}
      <section style={styles.productsSection} ref={setSectionRef(4)}>
        <div style={styles.productsHeader}>
          <h2 style={styles.productsTitle}>המוצרים שלנו</h2>
        </div>
        <div style={styles.productsGrid}>
          {products.map((product, index) => (
            <div key={index} style={styles.productItem(index)}>
              <span style={styles.productNumber}>0{index + 1}</span>
              <span style={styles.productName}>{product.trim()}</span>
              <span style={styles.productIcon}>
                <PlayIcon />
              </span>
            </div>
          ))}
        </div>
      </section>

      {/* Clients Section */}
      <section style={styles.clientsSection} ref={setSectionRef(5)}>
        <div style={styles.clientsContent}>
          <div style={styles.clientsLabel}>הלקוחות שלנו</div>
          <div style={styles.clientsMarquee}>
            {clients.map((client, index) => (
              <span key={index} style={styles.clientTag(index)}>{client.trim()}</span>
            ))}
          </div>
        </div>
      </section>

      {/* CTA Section */}
      <section style={styles.ctaSection} ref={setSectionRef(6)}>
        <h2 style={styles.ctaTitleStyle}>{ctaTitle}</h2>
        <button 
          style={styles.ctaButtonStyle}
          onMouseEnter={(e) => {
            e.target.style.backgroundColor = primaryTextColor;
            e.target.style.color = backgroundColor;
          }}
          onMouseLeave={(e) => {
            e.target.style.backgroundColor = 'transparent';
            e.target.style.color = primaryTextColor;
          }}
        >
          {ctaButton}
          <ArrowIcon />
        </button>
      </section>

      {/* Footer */}
      <footer style={styles.footer}>
        <div>{companyName}</div>
        <div>© {new Date().getFullYear()}</div>
      </footer>
    </div>
  );
}
